<?php`nob_start();`n/*`n * CORS: only reflect the Origin (with credentials) for known frontend origins.`n * This prevents cross-site credential theft while keeping the Vite dev server`n * (http://localhost:5173) and any production origin in ALLOWED_ORIGINS working.`n * Same-origin requests (production deploy under /lake-shore-id-editor) send no`n * Origin header and therefore need no CORS headers at all.`n * Configure ALLOWED_ORIGINS in config.php / environment for production domains.`n */`n$allowedOrigins = defined('ALLOWED_ORIGINS') ? ALLOWED_ORIGINS : [`n    'http://localhost:5173',`n];`n$origin = $_SERVER['HTTP_ORIGIN'] ?? '';`nif ($origin !== '' && in_array($origin, $allowedOrigins, true)) {`n    header('Access-Control-Allow-Origin: ' . $origin);`n    header('Access-Control-Allow-Credentials: true');`n    header('Vary: Origin');`n}`nheader('Access-Control-Allow-Methods: GET, POST, OPTIONS');`nheader('Access-Control-Allow-Headers: Content-Type, X-CSRF-Token');`nif ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') exit;`nrequire_once __DIR__ . '/config.php';`nrequire_once __DIR__ . '/auth.php.php';`nrequire_once __DIR__ . '/audit.php';`nrequire_once __DIR__ . '/rate_limit.php';`nrequire_once __DIR__ . '/import.php';`nrequire_once __DIR__ . '/photos.php';`n`nfunction response($data, int $status = 200): void { if (!headers_sent()) header('Content-Type: application/json; charset=utf-8'); http_response_code($status); echo json_encode($data); exit; }`nfunction input(): array { $raw=file_get_contents('php://input'); $json=json_decode($raw,true); return is_array($json)?$json:$_POST; }`nfunction uploadImage(string $field, string $folder, string $sub = ''): string {`n  if (!isset($_FILES[$field]) || $_FILES[$field]['error'] !== UPLOAD_ERR_OK) return '';`n  $allowedMimes=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];`n  $mime=mime_content_type($_FILES[$field]['tmp_name']);`n  if (!isset($allowedMimes[$mime])) response(['success'=>false,'message'=>'Only PNG, JPG or WEBP images are allowed'],422);`n  $dir=__DIR__.'/uploads/'.$folder.($sub===''?'':'/'.$sub); if (!is_dir($dir)) mkdir($dir,0775,true);`n  $prefix=($sub===''?$folder:$folder.'_'.$sub).'_';`n  $filename=$prefix.time().'_'.bin2hex(random_bytes(4)).'.'.$allowedMimes[$mime];`n  /* Security: also validate the file extension against the allowed list.`n   * Without this an attacker could upload a .php file with image MIME bytes. */`n  $ext = strtolower(pathinfo($_FILES[$field]['name'], PATHINFO_EXTENSION));`n  $allowedExts = ['png','jpg','jpeg','webp'];`n  if (!in_array($ext, $allowedExts, true)) {`n    response(['success'=>false,'message'=>'Invalid file extension. Only PNG, JPG or WEBP images are allowed'],422);`n  }`n  if (!move_uploaded_file($_FILES[$field]['tmp_name'],$dir.'/'.$filename)) response(['success'=>false,'message'=>'Upload failed'],500);`n  /* The returned relative path must include the sub-folder so the stored`n   * location and the canonical path always match (processed cutouts). */`n  return 'uploads/'.$folder.($sub===''?'':'/'.$sub).'/'.$filename;`n}`nfunction uploadDocument(string $field, string $folder): string {`n  if (!isset($_FILES[$field]) || $_FILES[$field]['error'] !== UPLOAD_ERR_OK) return '';`n  $allowedMimes=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp','application/pdf'=>'pdf'];`n  $mime=mime_content_type($_FILES[$field]['tmp_name']);`n  if (!isset($allowedMimes[$mime])) response(['success'=>false,'message'=>'Only PNG, JPG, WEBP images or PDF receipt documents are allowed'],422);`n  $dir=__DIR__.'/uploads/'.$folder; if (!is_dir($dir)) mkdir($dir,0775,true);`n  $filename=$folder.'_'.time().'_'.bin2hex(random_bytes(4)).'.'.$allowedMimes[$mime];`n  /* Security: validate extension in addition to MIME type */`n  $ext = strtolower(pathinfo($_FILES[$field]['name'], PATHINFO_EXTENSION));`n  $allowedExts = ['png','jpg','jpeg','webp','pdf'];`n  if (!in_array($ext, $allowedExts, true)) {`n    response(['success'=>false,'message'=>'Invalid file extension. Only PNG, JPG, WEBP images or PDF are allowed'],422);`n  }`n  if (!move_uploaded_file($_FILES[$field]['tmp_name'],$dir.'/'.$filename)) response(['success'=>false,'message'=>'Upload failed'],500);`n  return 'uploads/'.$folder.'/'.$filename;`n}`n`nfunction photoValidate(string $tmp, string $origName, int $maxBytes = 10485760): array {`n  /* Server-side student photo validation. Never trust the client alone:`n   * MIME by content, extension, byte size and readable image dimensions. */`n  $allowedMimes=['image/png'=>true,'image/jpeg'=>true,'image/webp'=>true];`n  $allowedExts=['png','jpg','jpeg','webp'];`n  $mime=mime_content_type($tmp);`n  if (!isset($allowedMimes[$mime])) return ['ok'=>false,'message'=>'Only PNG, JPG or WEBP student photos are allowed'];`n  $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));`n  if (!in_array($ext, $allowedExts, true)) return ['ok'=>false,'message'=>'Invalid file extension. Only PNG, JPG or WEBP images are allowed'];`n  if (filesize($tmp) > $maxBytes) return ['ok'=>false,'message'=>'Photo is too large (max '.(int)($maxBytes/1048576).' MB)'];`n  $info=getimagesize($tmp);`n  if (!is_array($info) || !isset($info[0]) || !isset($info[1])) return ['ok'=>false,'message'=>'The image file is invalid or corrupted'];`n  $w=(int)$info[0]; $h=(int)$info[1];`n  if ($w < 96 || $h < 96) return ['ok'=>false,'message'=>'Image resolution is too low for an ID photo (minimum 96×96 px)'];`n  if ($w > 12000 || $h > 12000) return ['ok'=>false,'message'=>'Image dimensions are too large (max 12000 px per side)'];`n  return ['ok'=>true,'mime'=>$mime,'ext'=>$allowedMimes[$mime],'w'=>$w,'h'=>$h];`n}`nfunction uploadStudentImage(string $field, string $sub = ''): string {`n  if (!isset($_FILES[$field]) || $_FILES[$field]['error'] !== UPLOAD_ERR_OK) response(['success'=>false,'message'=>'No photo selected or the upload failed'],422);`n  $chk=photoValidate($_FILES[$field]['tmp_name'], $_FILES[$field]['name']);`n  if ($chk['ok']!==true) response(['success'=>false,'message'=>$chk['message']],422);`n  return uploadImage($field,'students',$sub);`n}`nfunction deleteTemporaryUpload(string $rel): bool {`n  /* Remove a photo uploaded by this system only (generated names under`n   * uploads/students/). The canonical path must stay inside the student`n   * uploads directory — this blocks traversal attacks. */`n  if ($rel==='') return false;`n  $abs=realpath(__DIR__.'/'.$rel);`n  if (!$abs) return false;`n  $abs=str_replace('\\','/',$abs);`n  $studDir=(string)realpath(__DIR__.'/uploads/students');`n  if ($studDir==='') return false;`n  $studDir=str_replace('\\','/',$studDir);`n  if (!str_starts_with($abs.'/', $studDir.'/')) return false;`n  $base=pathinfo($abs, PATHINFO_BASENAME);`n  if (!preg_match('/^(students|students_processed)_[0-9]+_[0-9a-f]{8}[.](png|jpg|jpeg|webp)$/i', $base)) return false;`n  try { return unlink($abs) === true; } catch (Throwable $e) { return false; }`n}`n/*`n * Type-specific field validation & normalisation shared by both card-creation`n * paths (public studentSaveCard + staff saveCard). Mirrors the frontend rules:`n *   COLLEGE     -> course required (allowlist), grade_level & LRN cleared`n *   JUNIOR_HIGH -> grade_level required (GRADE 7-10), course cleared`n *   SENIOR_HIGH -> grade_level required (GRADE 11-12), course cleared`n *   LRN (basic ed only) -> optional, but if present must be exactly 12 digits`n * Returns null when the payload is valid, or ['message'=>..,'code'=>..].`n */`nfunction normalizeCardByType(array &$values): ?array {`n  $type=(string)$values['id_type'];`n  if ($type==='COLLEGE') {`n    $values['grade_level']=''; $values['lrn']='';`n    if ($values['course']==='') return ['message'=>'Please select a course for college students','code'=>422];`n    if (!in_array($values['course'],[`n      'BACHELOR OF SCIENCE IN PSYCHOLOGY','BACHELOR OF SPECIAL NEEDS EDUCATION',`n      'BACHELOR OF TECHNOLOGY AND LIVELIHOOD EDUCATION','BACHELOR OF SCIENCE IN ACCOUNTANCY',`n      'BACHELOR OF SCIENCE IN REAL ESTATE MANAGEMENT','BACHELOR OF SCIENCE IN TOURISM MANAGEMENT',`n      'BACHELOR OF SCIENCE IN MANAGEMENT ACCOUNTING','BACHELOR OF SCIENCE IN CRIMINOLOGY'],true))`n      return ['message'=>'Please select a valid course','code'=>422];`n  } else {`n    $values['course']='';`n    if ($values['grade_level']==='') return ['message'=>'Please select a grade level','code'=>422];`n    $band=$type==='JUNIOR_HIGH'?['GRADE 7','GRADE 8','GRADE 9','GRADE 10']:['GRADE 11','GRADE 12'];`n    if (!in_array($values['grade_level'],$band,true)) return ['message'=>'Please select a valid grade level for this department','code'=>422];`n  }`n  if ($values['lrn']!=='' && !preg_match('/^\d{12}$/',$values['lrn']))`n    return ['message'=>'LRN must be exactly 12 digits','code'=>422];`n  /* Nullable FK id columns must become NULL when the client omits them —`n   * strict SQL mode rejects '' for an INT column (blank signatory in the UI).`n   * template_id is a VERSION row; template_version is pinned alongside it. */`n  foreach (['signatory_id','template_id','preferred_photo_id'] as $fk) {`n    $fv=trim((string)($values[$fk]??''));`n    $values[$fk]=($fv==='')?null:(int)$fv;`n  }`n  $tv=trim((string)($values['template_version']??''));`n  $values['template_version']=($tv==='')?null:(int)$tv;`n  return null;`n}`n`n/*`n |--------------------------------------------------------------------------`n | Binding values to a card write`n |--------------------------------------------------------------------------`n | The card INSERT/UPDATE statements are built from a field list: the same`n | list produces the column names, the ":field" placeholders AND the values`n | handed to execute(). PDO compares the two lists and raises`n |   SQLSTATE[HY093] Invalid parameter number: number of bound variables`n |   does not match number of tokens`n | as soon as the value array holds even ONE key the statement does not`n | name (a missing key fails the same way).`n |`n | That makes the two lists easy to drift apart: the helpers that normalise`n | a payload are free to add keys — normalizeCardByType() always sets`n | template_version, which is deliberately NOT a column of the public`n | portal's field list, so studentSaveCard bound 37 values to a 36-column`n | INSERT and every public submission failed with HY093.`n |`n | cardBindValues() projects the value array onto exactly the fields the`n | statement names, so the two can never disagree again.`n */`nfunction cardBindValues(array $values, array $boundFields): array {`n    return array_intersect_key($values, array_flip($boundFields));`n}`n`n/*`n|--------------------------------------------------------------------------`n| Public student-number search (existing record detection)`n|--------------------------------------------------------------------------`n| The lookup helpers below back the unauthenticated `studentLookup` action.`n| They are deliberately small and self-contained: the search reuses the`n| existing id_cards table and the same identifier triple the duplicate check`n| on studentSaveCard already treats as a student's identity, so no second`n| source of truth is introduced.`n*/`n`n/*`n * Columns the public search may return, in display order.`n *`n * studentLookup is unauthenticated, so it exposes ONLY what the public form`n * needs to re-fill itself. Photos, addresses, emergency contacts, staff`n * notes and the whole print/release lifecycle stay in the database. The`n * response is assembled from these keys and never from the raw row, so`n * adding a column to id_cards can never leak it by accident. Keep this list`n * and the PUBLIC_LOOKUP_FIELDS constant in frontend/src/main.jsx in sync.`n */`nfunction studentLookupColumns(): array {`n  return ['student_name','id_type','course','grade_level','section_name',`n          'student_number','student_id_number','lrn','academic_year','school_year'];`n}`n`n/*`n * Sanitise a Student Number typed into the public search form.`n *`n * The value is always bound as a parameter (never concatenated into SQL),`n * but it is still validated as a school identifier: control characters and`n * zero-width copy/paste noise are stripped, the remainder must match the`n * shape the school actually prints, and anything wider than the column is`n * REJECTED rather than truncated — a truncated value could otherwise match a`n * different student.`n *`n * Returns the cleaned, upper-cased identifier, or '' when the input is not a`n * usable Student Number (empty, too short, wrong characters, too long).`n */`nfunction normalizeStudentNumber(string $raw): string {`n  $v = trim($raw);`n  if ($v === '') return '';`n  /* preg_replace() returns null on an invalid UTF-8 sequence, so fall back to`n   * the byte-safe control-character strip rather than trusting a null. */`n  $clean = preg_replace('/[\x00-\x1F\x7F]|\xE2\x80[\x80-\x8B\xAF]|\xEF\xBB\xBF/', '', $v);`n  if ($clean === null) $clean = preg_replace('/[\x00-\x1F\x7F]/', '', $v);`n  $clean = trim((string)$clean);`n  /* Must start with a letter or digit; the rest is the separator set the`n   * school uses (2026-00125, 2026/00125, 2026_00125, ...). Anything else —`n   * SQL metacharacters, wildcards, markup — is refused. */`n  if (!preg_match('/^[A-Za-z0-9][A-Za-z0-9\-\/_. ]*$/', $clean)) return '';`n  if (strlen($clean) > 100) return '';   /* VARCHAR(100): reject, never cut */`n  return strtoupper($clean);`n}`n`n/*`n|--------------------------------------------------------------------------`n| Template versioning`n|--------------------------------------------------------------------------`n| A template row IS one version of a design. `parent_id` points every`n| version at the same family root, and UNIQUE(parent_id, version) means an`n| existing version can never be overwritten or duplicated — the database`n| rejects it, not just the API.`n|`n| The helpers below are the single place that knows these rules, so the`n| template endpoints, the ID generation path and the reprint path all agree.`n*/`n`n/* Read one template version, or null. */`nfunction templateVersionById(PDO $pdo, int $id): ?array {`n  if ($id <= 0) return null;`n  $st = $pdo->prepare('SELECT * FROM id_templates WHERE id=?');`n  $st->execute([$id]);`n  $row = $st->fetch();`n  return $row ?: null;`n}`n`n/* The family's root (v1) id. Pre-versioning rows are their own root. */`nfunction templateFamilyRootId(array $tpl): int {`n  $parent = (int)($tpl['parent_id'] ?? 0);`n  return $parent > 0 ? $parent : (int)$tpl['id'];`n}`n`n/*`n * Next free version number in a family.`n *`n * Computed as MAX(version)+1 rather than a blind count: deleting a version`n * must never cause an existing number to be reused, which would silently`n * change what "v3" means. The UNIQUE index is the final backstop.`n */`nfunction nextTemplateVersionNo(PDO $pdo, int $rootId): int {`n  $st = $pdo->prepare('SELECT COALESCE(MAX(version),0) FROM id_templates WHERE parent_id=?');`n  $st->execute([$rootId]);`n  return (int)$st->fetchColumn() + 1;`n}`n`n/* The department's currently active template version, or null. */`nfunction activeTemplateVersion(PDO $pdo, string $idType): ?array {`n  $st = $pdo->prepare('SELECT * FROM id_templates WHERE id_type=? AND is_active=1 LIMIT 1');`n  $st->execute([$idType]);`n  $row = $st->fetch();`n  return $row ?: null;`n}`n`n/* How many IDs were generated from a specific template version. */`nfunction templateVersionUsage(PDO $pdo, int $templateId): int {`n  $st = $pdo->prepare('SELECT COUNT(*) FROM id_cards WHERE template_id=?');`n  $st->execute([$templateId]);`n  return (int)$st->fetchColumn();`n}`n`n/*`n|--------------------------------------------------------------------------`n| Pinning a template version onto a card`n|--------------------------------------------------------------------------`n| Called on every card write (create AND update).`n|`n| The rule the whole feature rests on: an ID keeps the version it was`n| generated with. On create we take the department's active version; on`n| update we only re-pin when the admin explicitly picked a different`n| template, so editing a student record can never silently restyle an`n| already-printed ID.`n|`n| Returns the [template_id, template_version] pair to store.`n*/`nfunction pinCardTemplateVersion(PDO $pdo, array &$values, int $cardId = 0): void {`n  $idType = (string)($values['id_type'] ?? '');`n  $chosen = $values['template_id'] ?? null;`n`n  if ($cardId > 0) {`n    /* Editing an existing ID: keep its pinned version unless the admin`n     * deliberately selected another template in the editor. */`n    $cur = $pdo->prepare('SELECT template_id, template_version FROM id_cards WHERE id=?');`n    $cur->execute([$cardId]);`n    $row = $cur->fetch();`n    $currentId = $row ? (int)($row['template_id'] ?? 0) : 0;`n    $currentVer = $row && $row['template_version'] !== null ? (int)$row['template_version'] : null;`n`n    if ($currentId > 0) {`n      if (!$chosen || (int)$chosen === $currentId) {`n        $values['template_id'] = $currentId;`n        $values['template_version'] = $currentVer;`n        return;`n      }`n    }`n  }`n`n  /* New ID (or an explicit template change): resolve the version row and`n   * store both its id and its number. */`n  $tpl = $chosen ? templateVersionById($pdo, (int)$chosen) : activeTemplateVersion($pdo, $idType);`n  if (!$tpl) {`n    $values['template_id'] = null;`n    $values['template_version'] = null;`n    return;`n  }`n  /* Never let a card point at a template from a different department. */`n  if ($tpl['id_type'] !== $idType) {`n    $tpl = activeTemplateVersion($pdo, $idType);`n  }`n  if (!$tpl) {`n    $values['template_id'] = null;`n    $values['template_version'] = null;`n    return;`n  }`n  $values['template_id'] = (int)$tpl['id'];`n  $values['template_version'] = (int)$tpl['version'];`n}`n$action=$_GET['action']??'';`n$action=$_GET['action']??'';`ntry {`n  $pdo=db();`n`n  if ($action==='login' && $_SERVER['REQUEST_METHOD']==='POST') {`n    $d=input();`n    $username=trim((string)($d['username']??''));`n    $password=(string)($d['password']??'');`n    if ($username==='' || $password==='') response(['success'=>false,'message'=>'Username and password are required'],422);`n    /* BINARY forces a case-sensitive username match (AUTH-010). */`n    $stmt=$pdo->prepare('SELECT id,username,password,full_name,role,is_active FROM users WHERE BINARY username=? LIMIT 1');`n    $stmt->execute([$username]);`n    $user=$stmt->fetch();`n    if (!$user || (int)$user['is_active']!==1 || !password_verify($password,$user['password'])) {`n      auditLog('login_failed','user',$user?(int)$user['id']:null,['attempted_username'=>$username],null,$user?(int)$user['id']:null);`n      response(['success'=>false,'message'=>'Invalid username or password'],401);`n    }`n    loginUser($user);`n    auditLog('login','user',(int)$user['id'],null,['username'=>$user['username'],'role'=>$user['role']]);`n    response(['success'=>true,'data'=>currentUser(),'csrf_token'=>generateCsrfToken()]);`n  }`n`n  if ($action==='logout' && $_SERVER['REQUEST_METHOD']==='POST') {`n    $auditUid=isset($_SESSION['user_id'])?(int)$_SESSION['user_id']:null;`n    logoutUser();`n    auditLog('logout','user',$auditUid,null,null,$auditUid);`n    response(['success'=>true]);`n  }`n`n  if ($action==='me' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $u=currentUser();`n    if (!$u) response(['success'=>false,'message'=>'Not authenticated'],401);`n    response(['success'=>true,'data'=>$u,'csrf_token'=>generateCsrfToken()]);`n  }`n`n  if ($action==='forgotPassword' && $_SERVER['REQUEST_METHOD']==='POST') {`n    $d=input(); $username=trim((string)($d['username']??''));`n    if($username==='') response(['success'=>false,'message'=>'Enter your username or email'],422);`n    $stmt=$pdo->prepare('SELECT id,is_active FROM users WHERE BINARY username=? LIMIT 1');$stmt->execute([$username]);$u=$stmt->fetch();`n    if(!$u || (int)$u['is_active']!==1) response(['success'=>true,'message'=>'If the account exists, a reset token has been generated.']);`n        $token=bin2hex(random_bytes(16));`n    $pdo->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([(int)$u['id'],hash('sha256',$token)]);`n    /* NOTE: The reset token must be sent out-of-band (e.g. email).`n     * It is deliberately NOT returned in the API response to prevent token disclosure. */`n    response(['success'=>true,'message'=>'If the account exists, a reset token has been generated. Valid for 30 minutes.']);`n  }`n`n  if ($action==='resetPassword' && $_SERVER['REQUEST_METHOD']==='POST') {`n    $d=input(); $token=(string)($d['token']??''); $password=(string)($d['password']??'');`n    if($token===''||strlen($password)<6) response(['success'=>false,'message'=>'A valid token and a password of at least 6 characters are required'],422);`n    $stmt=$pdo->prepare('SELECT id,user_id FROM password_resets WHERE token_hash=? AND used=0 AND expires_at>NOW() ORDER BY id DESC LIMIT 1');`n    $stmt->execute([hash('sha256',$token)]);$pr=$stmt->fetch();`n    if(!$pr) response(['success'=>false,'message'=>'Invalid or expired reset token'],422);`n    $pdo->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),(int)$pr['user_id']]);`n    $pdo->prepare('UPDATE password_resets SET used=1 WHERE id=?')->execute([(int)$pr['id']]);`n    auditLog('password_reset','user',(int)$pr['user_id'],null,null,(int)$pr['user_id']);`n    response(['success'=>true,'message'=>'Password updated. You can now sign in.']);`n  }`n`n  /*`n  |--------------------------------------------------------------------------`n  | Public student self-service ID creation (no login required)`n  |--------------------------------------------------------------------------`n  */`n  if ($action==='publicSignatory' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $type=trim($_GET['type']??'');`n    $map=['COLLEGE'=>'Sherill S. Villaluz','JUNIOR_HIGH'=>'Annabelle V. Molina','SENIOR_HIGH'=>'Annabelle V. Molina'];`n    $name=$map[$type]??'';`n    if ($name==='') response(['success'=>true,'data'=>null]);`n    $stmt=$pdo->prepare('SELECT id,full_name,signature_path FROM signatories WHERE full_name=? AND is_active=1 LIMIT 1');`n    $stmt->execute([$name]);`n    $row=$stmt->fetch();`n    response(['success'=>true,'data'=>$row ?: ['id'=>null,'full_name'=>$name,'signature_path'=>'']]);`n  }`n  /* Self-hosted verification challenge (SVG) for a client that ran into`n   * the public rate limit. Issuance has its own per-IP budget so the`n   * endpoint itself cannot be abused; answering a challenge unlocks a`n   * few extra submissions for the current window (see rate_limit.php). */`n  if ($action==='publicCaptcha' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $challenge=rlIssueChallenge('public:studentPortal');`n    if (!$challenge['ok']) {`n      $wait=max(1,(int)($challenge['retry_after']??60));`n      if (($challenge['reason']??'')==='limited') {`n        header('Retry-After: '.$wait);`n        response(['success'=>false,'message'=>'Too many verification requests from your network. Please try again in '.rlHumanWait($wait).'.','retry_after'=>$wait],429);`n      }`n      response(['success'=>false,'message'=>'Verification is temporarily unavailable. Please try again in a few minutes.'],503);`n    }`n    response(['success'=>true,'captcha_id'=>$challenge['id'],'image'=>$challenge['image'],'expires_in'=>$challenge['expires_in']]);`n  }`n  /*`n   * Existing-student detection (no login required).`n   *`n   * Workflow: Enter Student Number -> Search -> Student Found -> the React`n   * form is filled in automatically. Answers 404 "Student Not Found" when`n   * no record carries that identifier.`n   *`n   * Anti-enumeration measures (an unauthenticated read of the student`n   * table is the most sensitive thing this portal can do):`n   *   - exact match only, never LIKE, so numbers cannot be walked one`n   *     prefix at a time;`n   *   - LIMIT 1, so a call returns a single record and never a list;`n   *   - a minimum length below which nothing is ever sent to the database;`n   *   - the response is re-keyed through studentLookupColumns(), so photos,`n   *     addresses, contacts and print/release state cannot leak;`n   *   - rlGuard() applies the same per-IP policy, honeypot and captcha`n   *     escape hatch as the other public endpoints, in its own bucket.`n   */`n  if ($action==='studentLookup' && $_SERVER['REQUEST_METHOD']==='POST') {`n    $data=input();`n    /* Rate limit + bot trap BEFORE any validation or database read. */`n    rlGuard('studentLookup', $data);`n    $number=normalizeStudentNumber((string)($data['student_number']??''));`n    if ($number==='' || strlen($number)<4)`n      response(['success'=>false,'message'=>'Please enter a valid Student Number (at least 4 characters).'],422);`n    /* The three identifier columns are the same triple the duplicate check on`n     * studentSaveCard uses, so searching by any of them finds the record the`n     * create form would have refused as a duplicate. */`n    $lookupCols=implode(',',studentLookupColumns());`n    $stmt=$pdo->prepare("SELECT id,$lookupCols FROM id_cards`n                         WHERE student_number=? OR student_id_number=? OR lrn=?`n                         ORDER BY updated_at DESC, id DESC LIMIT 1");`n    $stmt->execute([$number,$number,$number]);`n    $row=$stmt->fetch();`n    if (!$row)`n      response(['success'=>false,'message'=>'Student Not Found. No ID record matches that Student Number.'],404);`n    $found=[];`n    foreach (studentLookupColumns() as $col) $found[$col]=(string)($row[$col]??'');`n    auditLog('student_lookup','id_card',(int)$row['id'],null,['student_number'=>$found['student_number']]);`n    response(['success'=>true,'data'=>$found,'card_id'=>(int)$row['id']]);`n  }`n  if ($action==='studentUploadPhoto' && $_SERVER['REQUEST_METHOD']==='POST') {`n    /* Rate limit BEFORE touching the upload: a throttled client must`n     * not be able to push files onto the server at all. */`n    rlGuard('studentUploadPhoto', $_POST);`n    response(['success'=>true,'path'=>uploadStudentImage('photo')]);`n  }`n  if ($action==='studentSaveCard' && $_SERVER['REQUEST_METHOD']==='POST') {`n    $data=input();`n    /* Rate limit + bot trap before any validation or database write. */`n    rlGuard('studentSaveCard', $data);`n    $studentName=trim((string)($data['student_name']??''));`n    $idType=trim((string)($data['id_type']??''));`n    /* Input length validation */`n    $course=trim((string)($data['course']??''));`n    if ($studentName !== '' && strlen($studentName) > 150) response(['success'=>false,'message'=>'Student name is too long (max 150 characters)'],422);`n    if (strlen($idType) > 20) response(['success'=>false,'message'=>'Invalid department'],422);`n    if (strlen($course) > 255) response(['success'=>false,'message'=>'Course is too long'],422);`n    if ($studentName==='') response(['success'=>false,'message'=>'Please enter the student full name'],422);`n    if (!in_array($idType,['COLLEGE','JUNIOR_HIGH','SENIOR_HIGH'],true)) response(['success'=>false,'message'=>'Please select a valid department'],422);`n    $fields=['student_name','id_type','course','grade_level','section_name','student_number','student_id_number','lrn','academic_year','school_year','photo_path','preferred_photo_id','address_line1','address_line2','emergency_label','emergency_contact','emergency_phone','terms_title','term_1','term_2','term_3','institution_name','institution_address','mobile_no','telephone_no','email_address','signatory_id','signatory_name','signature_path','template_id','original_photo_path','photo_processing_status','photo_processed_at','photo_crop','background_mode','background_color'];`n    $values=[];foreach($fields as $f)$values[$f]=trim((string)($data[$f]??''));`n    /* Photo processing metadata (kept neutral when not provided) */`n    if (in_array($values['photo_processing_status']??'original',['original','processed','uploaded','failed'],true)===false) $values['photo_processing_status']='original';`n    /* Background mode validation */`n    if (!in_array($values['background_mode']??'transparent',['transparent','white','custom'],true)) $values['background_mode']='transparent';`n    /* Background color validation (must be a valid HEX color) */`n    if (!preg_match('/^#[0-9A-Fa-f]{6}$/',$values['background_color']??'')) $values['background_color']='#FFFFFF';`n    /* The UI sends an ISO-8601 timestamp (new Date().toISOString()); MySQL`n     * DATETIME needs 'Y-m-d H:i:s' — normalise so strict mode accepts it. */`n    $ppa=trim((string)($values['photo_processed_at']??''));`n    if ($ppa==='') { $values['photo_processed_at']=null; }`n    else { $ts=strtotime($ppa); $values['photo_processed_at']=$ts?date('Y-m-d H:i:s',$ts):null; }`n    /* Type-specific validation & mapping (shared helper; mirrors the UI rules) */`n    if ($err=normalizeCardByType($values)) response(['success'=>false,'message'=>$err['message']],$err['code']);`n    /* Serialize duplicate-check + insert so parallel identical submissions`n     * cannot race past the check and create duplicate rows (QA concurrency §24). */`n    $gotLock=(int)$pdo->query("SELECT GET_LOCK('lsc_card_write',10)")->fetchColumn();`n    if ($gotLock!==1) response(['success'=>false,'message'=>'Server is busy, please try again shortly'],503);`n    /* Duplicate prevention */`n    $sn=trim((string)$values['student_number']);`n    $sid=trim((string)$values['student_id_number']);`n    $lrn=trim((string)$values['lrn']);`n    $dupCols=[];$dupParams=[];`n    if ($sn !== '')  { $dupCols[]='student_number=?';      $dupParams[]=$sn; }`n    if ($sid !== '') { $dupCols[]='student_id_number=?';   $dupParams[]=$sid; }`n    if ($lrn !== '') { $dupCols[]='lrn=?';                 $dupParams[]=$lrn; }`n    if ($dupCols) {`n      array_unshift($dupParams, $studentName);`n      $dupCheck=$pdo->prepare('SELECT id FROM id_cards WHERE student_name=? AND ('.implode(' OR ',$dupCols).') LIMIT 1');`n      $dupCheck->execute($dupParams);`n      $dup = $dupCheck->fetch();`n      if ($dup) {`n        $pdo->query("SELECT RELEASE_LOCK('lsc_card_write')");`n        response(['success'=>false,'message'=>'A student with this name and student number/ID/LRN already exists.'],409);`n      }`n      /* no duplicate: KEEP holding the lock until after the insert */`n    }`n    /* A record the public search already located must never be turned into a`n     * second row by submitting the form again. The id is re-verified against`n     * the database (so a crafted payload cannot aim at somebody else's record)`n     * and only counts while it still carries one of the submitted identifiers.`n     * Runs inside the same write lock as the duplicate check above. */`n    $existingId=(int)($data['existing_card_id']??0);`n    if ($existingId>0) {`n      $exCols=[];$exParams=[$existingId];`n      if ($sn  !== '') { $exCols[]='student_number=?';    $exParams[]=$sn; }`n      if ($sid !== '') { $exCols[]='student_id_number=?'; $exParams[]=$sid; }`n      if ($lrn !== '') { $exCols[]='lrn=?';               $exParams[]=$lrn; }`n      if ($exCols) {`n        $exCheck=$pdo->prepare('SELECT id FROM id_cards WHERE id=? AND ('.implode(' OR ',$exCols).') LIMIT 1');`n        $exCheck->execute($exParams);`n        if ($exCheck->fetch()) {`n          $pdo->query("SELECT RELEASE_LOCK('lsc_card_write')");`n          response(['success'=>false,'message'=>'An ID record already exists for this Student Number, so a second one cannot be created. If you need a replacement, please use "Report Lost ID".'],409);`n        }`n      }`n    }`n    $cols=implode(',',$fields);$pars=implode(',',array_map(fn($f)=>":$f",$fields));`n    $stmt=$pdo->prepare("INSERT INTO id_cards($cols) VALUES($pars)");$stmt->execute(cardBindValues($values,$fields));`n    $id=(int)$pdo->lastInsertId();`n    $pdo->query("SELECT RELEASE_LOCK('lsc_card_write')");`n    auditLog('card_created','id_card',$id,null,['student_name'=>$values['student_name'],'student_number'=>$values['student_number'],'id_type'=>$values['id_type'],'status'=>'created']);`n    response(['success'=>true,'id'=>$id,'message'=>'Your ID request has been submitted successfully.']);`n  }`n    if ($action==='lostIdRequest' && $_SERVER['REQUEST_METHOD']==='POST') {`n    $data=input();`n    /* Rate limit + bot trap before the ID lookup, the receipt upload`n     * and the database insert. */`n    rlGuard('lostIdRequest', $data);`n    $studentName=trim((string)($data['student_name']??''));`n    $idType=trim((string)($data['id_type']??''));`n    if ($studentName==='') response(['success'=>false,'message'=>'Please enter the student full name'],422);`n    if (!in_array($idType,['COLLEGE','JUNIOR_HIGH','SENIOR_HIGH'],true)) $idType='COLLEGE';`n    $course=trim((string)($data['course']??''));`n    $gradeLevel=trim((string)($data['grade_level']??''));`n    $sectionName=trim((string)($data['section_name']??''));`n    $studentNumber=trim((string)($data['student_number']??''));`n    $lrn=trim((string)($data['lrn']??''));`n`n    /*`n     * The lost ID report must refer to an ID that already exists in the`n     * system. The details the student filled in are used as the search`n     * reference against the id_cards table (name + student number / ID`n     * number / LRN). If no matching ID is created in the system the`n     * request is rejected and nothing is saved — including the receipt,`n     * which is uploaded ONLY after a matching ID is found.`n     */`n    $identifier=$studentNumber!==''?$studentNumber:$lrn;`n    if ($identifier==='') {`n      response(['success'=>false,'message'=>'Please provide the Student / ID Number (or LRN) so your ID can be checked in the system.'],422);`n    }`n    $stmt=$pdo->prepare('SELECT id,student_name,id_type,student_number,student_id_number,lrn,course,grade_level,section_name FROM id_cards WHERE student_name=? AND (student_number=? OR student_id_number=? OR lrn=?) ORDER BY (id_type=?) DESC, updated_at DESC LIMIT 1');`n    $stmt->execute([$studentName,$identifier,$identifier,$identifier,$idType]);`n    $m=$stmt->fetch();`n    if (!$m) {`n      response([`n        'success'=>false,`n        'message'=>'No ID found in the system. The details you entered do not match any ID created in the ID Management System. Please make sure your ID has already been created in the system before reporting it as lost.',`n      ],404);`n    }`n    $referenceCardId=(int)$m['id'];`n`n    // Upload receipt only AFTER we've confirmed the ID exists in the system`n    $receipt=uploadDocument('receipt','receipts');`n`n    $pdo->prepare("INSERT INTO lost_id_requests(student_name,id_type,course,grade_level,section_name,student_number,lrn,reference_card_id,status,receipt_path) VALUES(?,?,?,?,?,?,?,?,'pending',?)")`n      ->execute([$studentName,$idType,$course,$gradeLevel,$sectionName,$studentNumber,$lrn,$referenceCardId,$receipt]);`n    response(['success'=>true,'id'=>(int)$pdo->lastInsertId(),'reference_card_id'=>$referenceCardId,'message'=>'Your lost ID reprint request has been submitted. The administrator will review your request.']);`n  }`n`n  requireLogin();`n`n  if ($action==='uploadPhoto' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf();`n    $studentId = (int)($_POST['student_id'] ?? 0);`n    if ($studentId > 0) {`n      // New path: record in centralized photo library`n      if (!isset($_FILES['photo']) || $_FILES['photo']['error'] !== UPLOAD_ERR_OK)`n        response(['success'=>false,'message'=>'No photo selected or upload failed'],422);`n      $val = photoLibraryValidate($_FILES['photo']['tmp_name'], $_FILES['photo']['name']);`n      if ($val['ok'] !== true) response(['success'=>false,'message'=>$val['message']],422);`n      $pathInfo = photoStoragePath($studentId, 'ORIGINAL', $val['ext']);`n      $destAbs = $pathInfo['dir'] . '/' . basename($pathInfo['rel']);`n      if (!move_uploaded_file($_FILES['photo']['tmp_name'], $destAbs))`n        response(['success'=>false,'message'=>'Failed to save photo'],500);`n      $relPath = 'uploads/' . $pathInfo['rel'];`n      $me = currentUser();`n      $photoId = photoRecord($pdo, $studentId, 'CREATE_ID', 'ORIGINAL', null, $relPath, $val['mime'], filesize($destAbs), $val['w'], $val['h'], null, null, $me ? $me['id'] : null);`n      $pdo->prepare('UPDATE id_cards SET photo_path=?, preferred_photo_id=? WHERE id=?')->execute([$relPath, $photoId, $studentId]);`n      auditLog('PHOTO_UPLOADED','student_photo',$photoId,['student_id'=>$studentId,'source'=>'CREATE_ID'],['path'=>$relPath]);`n      response(['success'=>true,'photo_id'=>$photoId,'path'=>$relPath,'width'=>$val['w'],'height'=>$val['h']]);`n    }`n    // Legacy path (no student_id yet — frontend will re-upload with student_id after save)`n    response(['success'=>true,'path'=>uploadStudentImage('photo')]);`n  }`n`n  /* ===== Centralized Photo Library endpoints ===== */`n`n  if ($action==='photoLibraryUpload' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf();`n    $studentId = (int)($_POST['student_id'] ?? 0);`n    if ($studentId <= 0) response(['success'=>false,'message'=>'Invalid student'],422);`n    $chk = $pdo->prepare('SELECT id FROM id_cards WHERE id=?');`n    $chk->execute([$studentId]);`n    if (!$chk->fetch()) response(['success'=>false,'message'=>'Student record not found'],404);`n    if (!isset($_FILES['photo']) || $_FILES['photo']['error'] !== UPLOAD_ERR_OK)`n      response(['success'=>false,'message'=>'No photo selected or upload failed'],422);`n    $val = photoLibraryValidate($_FILES['photo']['tmp_name'], $_FILES['photo']['name']);`n    if ($val['ok'] !== true) response(['success'=>false,'message'=>$val['message']],422);`n    $label = trim((string)($_POST['label'] ?? ''));`n    $pathInfo = photoStoragePath($studentId, 'ORIGINAL', $val['ext'], $label !== '' ? $label : null);`n    $destAbs = $pathInfo['dir'] . '/' . basename($pathInfo['rel']);`n    if (!move_uploaded_file($_FILES['photo']['tmp_name'], $destAbs))`n      response(['success'=>false,'message'=>'Failed to save photo'],500);`n    $relPath = 'uploads/' . $pathInfo['rel'];`n    $me = currentUser();`n    $photoId = photoRecord($pdo, $studentId, 'CREATE_ID', 'ORIGINAL', null, $relPath, $val['mime'], filesize($destAbs), $val['w'], $val['h'], null, null, $me ? $me['id'] : null);`n    auditLog('PHOTO_UPLOADED','student_photo',$photoId,['student_id'=>$studentId,'source'=>'CREATE_ID'],['path'=>$relPath,'width'=>$val['w'],'height'=>$val['h']]);`n    response(['success'=>true,'photo_id'=>$photoId,'path'=>$relPath,'width'=>$val['w'],'height'=>$val['h']]);`n  }`n`n  if ($action==='deleteUpload' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d=input(); $rel=trim((string)($d['path']??'')); response(['success'=>true,'deleted'=>deleteTemporaryUpload($rel)]);`n  }`n`n  if ($action==='photoLibraryUploadProcessed' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf();`n    $studentId = (int)($_POST['student_id'] ?? 0);`n    $parentPhotoId = (int)($_POST['parent_photo_id'] ?? 0);`n    $backgroundMode = trim($_POST['background_mode'] ?? 'transparent');`n    $backgroundColor = trim($_POST['background_color'] ?? '#FFFFFF');`n    if ($studentId <= 0) response(['success'=>false,'message'=>'Invalid student'],422);`n    $chk = $pdo->prepare('SELECT id FROM id_cards WHERE id=?');`n    $chk->execute([$studentId]);`n    if (!$chk->fetch()) response(['success'=>false,'message'=>'Student record not found'],404);`n    if (!in_array($backgroundMode, ['transparent','white','custom'],true)) $backgroundMode='transparent';`n    if (!preg_match('/^#[0-9A-Fa-f]{6}$/',$backgroundColor)) $backgroundColor='#FFFFFF';`n    if (!isset($_FILES['photo']) || $_FILES['photo']['error'] !== UPLOAD_ERR_OK)`n      response(['success'=>false,'message'=>'No photo selected or upload failed'],422);`n    $val = photoLibraryValidate($_FILES['photo']['tmp_name'], $_FILES['photo']['name']);`n    if ($val['ok'] !== true) response(['success'=>false,'message'=>$val['message']],422);`n    $pathInfo = photoStoragePath($studentId, 'PROCESSED', $val['ext']);`n    $destAbs = $pathInfo['dir'] . '/' . basename($pathInfo['rel']);`n    if (!move_uploaded_file($_FILES['photo']['tmp_name'], $destAbs))`n      response(['success'=>false,'message'=>'Failed to save photo'],500);`n    $relPath = 'uploads/' . $pathInfo['rel'];`n    $bgInfo = ['mode' => $backgroundMode, 'color' => $backgroundColor];`n    $cropData = null;`n    if (!empty($_POST['crop_data'])) { $cd = json_decode($_POST['crop_data'], true); if (is_array($cd)) $cropData = $cd; }`n    $me = currentUser();`n    $photoId = photoRecord($pdo, $studentId, 'PHOTO_PROCESSING', 'PROCESSED',`n      $parentPhotoId > 0 ? $parentPhotoId : null, $relPath, $val['mime'],`n      filesize($destAbs), $val['w'], $val['h'], $bgInfo, $cropData, $me ? $me['id'] : null);`n    auditLog('PHOTO_PROCESSED','student_photo',$photoId,['student_id'=>$studentId,'source'=>'PHOTO_PROCESSING','parent_photo_id'=>$parentPhotoId ?: null],['path'=>$relPath,'background'=>$bgInfo]);`n    response(['success'=>true,'photo_id'=>$photoId,'path'=>$relPath,'width'=>$val['w'],'height'=>$val['h'],'background'=>$bgInfo]);`n  }`n`n  if ($action==='settings' && $_SERVER['REQUEST_METHOD']==='GET') { $rows=$pdo->query('SELECT setting_key,setting_value FROM system_settings')->fetchAll(); $out=[]; foreach($rows as $r)$out[$r['setting_key']]=$r['setting_value']; response(['success'=>true,'data'=>$out]); }`n`n  /* --- Photo Library: list for student --- */`n  if ($action==='photoLibraryList' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $studentId = (int)($_GET['student_id'] ?? 0);`n    if ($studentId <= 0) response(['success'=>false,'message'=>'Invalid student'],422);`n    $filters = ['source'=>trim($_GET['source']??''),'type'=>trim($_GET['type']??''),'is_active'=>$_GET['is_active']??'','processing_status'=>trim($_GET['processing_status']??'')];`n    $photos = photoListForStudent($pdo, $