copy($srcAbs, $destAbs)) response(['success'=>false,'message'=>'Failed to attach photo'],500);`n    $relPath = 'uploads/' . $pathInfo['rel'];`n    $img = @getimagesize($destAbs);`n    $me = currentUser();`n    $newId = photoRecord($pdo, $studentId, $src['source'], $src['type'],`n      (int)$src['id'], $relPath, $src['mime_type'], filesize($destAbs),`n      $img ? (int)$img[0] : (int)$src['width'], $img ? (int)$img[1] : (int)$src['height'],`n      $src['background_info'] ? json_decode($src['background_info'], true) : null,`n      $src['crop_data'] ? json_decode($src['crop_data'], true) : null,`n      $me ? $me['id'] : null);`n    $pdo->prepare('UPDATE id_cards SET preferred_photo_id=?, photo_path=? WHERE id=?')->execute([$newId, $relPath, $studentId]);`n    auditLog('PHOTO_CLONED','student_photo',$newId,['student_id'=>$studentId,'source_photo_id'=>$photoId],['path'=>$relPath]);`n    response(['success'=>true,'photo_id'=>$newId,'path'=>$relPath]);`n  }`n`n  /* --- Photo Library: set preferred photo --- */`n  if ($action==='photoLibrarySetPreferred' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d = input();`n    $photoId = (int)($d['photo_id'] ?? 0);`n    $studentId = (int)($d['student_id'] ?? 0);`n    if ($photoId <= 0 || $studentId <= 0) response(['success'=>false,'message'=>'Invalid photo or student'],422);`n    $photo = photoVerifyOwnership($pdo, $photoId, $studentId);`n    if (!$photo) response(['success'=>false,'message'=>'Photo not found or access denied'],404);`n    if (!$photo['is_active']) response(['success'=>false,'message'=>'Cannot select an archived photo'],422);`n    $pdo->prepare('UPDATE id_cards SET preferred_photo_id=?, photo_path=? WHERE id=?')->execute([$photoId, $photo['file_path'], $studentId]);`n    auditLog('PHOTO_SELECTED','student_photo',$photoId,['student_id'=>$studentId],['photo_id'=>$photoId]);`n    response(['success'=>true,'message'=>'Photo selected for ID']);`n  }`n`n  /* --- Photo Library: archive --- */`n  if ($action==='photoLibraryArchive' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d = input();`n    $photoId = (int)($d['photo_id'] ?? 0);`n    $studentId = (int)($d['student_id'] ?? 0);`n    if ($photoId <= 0 || $studentId <= 0) response(['success'=>false,'message'=>'Invalid photo or student'],422);`n    if (!photoVerifyOwnership($pdo, $photoId, $studentId)) response(['success'=>false,'message'=>'Photo not found or access denied'],404);`n    $ok = photoArchive($pdo, $photoId, $studentId);`n    auditLog('PHOTO_ARCHIVED','student_photo',$photoId,['student_id'=>$studentId],['archived'=>true]);`n    response(['success'=>$ok,'archived'=>$ok]);`n  }`n`n  /* --- Photo Library: restore --- */`n  if ($action==='photoLibraryRestore' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d = input();`n    $photoId = (int)($d['photo_id'] ?? 0);`n    $studentId = (int)($d['student_id'] ?? 0);`n    if ($photoId <= 0 || $studentId <= 0) response(['success'=>false,'message'=>'Invalid photo or student'],422);`n    if (!photoVerifyOwnership($pdo, $photoId, $studentId)) response(['success'=>false,'message'=>'Photo not found or access denied'],404);`n    $pdo->prepare('UPDATE student_photos SET is_active=1, type="ORIGINAL" WHERE id=? AND student_id=?')->execute([$photoId, $studentId]);`n    auditLog('PHOTO_RESTORED','student_photo',$photoId,['student_id'=>$studentId],['is_active'=>1]);`n    response(['success'=>true,'message'=>'Photo restored']);`n  }`n`n  /* --- Photo Library: permanent delete (removes record + file) --- */`n  if ($action==='photoLibraryDelete' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d = input();`n    $photoId = (int)($d['photo_id'] ?? 0);`n    if ($photoId <= 0) response(['success'=>false,'message'=>'Invalid photo'],422);`n    $stmt = $pdo->prepare('SELECT * FROM student_photos WHERE id=? LIMIT 1');`n    $stmt->execute([$photoId]);`n    $photo = $stmt->fetch();`n    if (!$photo) response(['success'=>false,'message'=>'Photo not found'],404);`n    /* Detach derived copies first so no row references a missing parent */`n    $pdo->prepare('UPDATE student_photos SET parent_photo_id=NULL WHERE parent_photo_id=?')->execute([$photoId]);`n    $pdo->prepare('DELETE FROM student_photos WHERE id=?')->execute([$photoId]);`n    $abs = photoSafePath($photo['file_path']);`n    if ($abs && file_exists($abs)) @unlink($abs);`n    /* If a card still points at the deleted photo, clear its selection */`n    $pdo->prepare('UPDATE id_cards SET preferred_photo_id=NULL, photo_path=IF(photo_path=?,"",photo_path) WHERE preferred_photo_id=?')`n        ->execute([$photo['file_path'], $photoId]);`n    auditLog('PHOTO_DELETED','student_photo',$photoId,['student_id'=>(int)$photo['student_id'],'file_path'=>$photo['file_path']],null);`n    response(['success'=>true,'message'=>'Photo deleted']);`n  }`n`n  /* --- Photo Library: replace the file behind an existing photo record --- */`n  if ($action==='photoLibraryReplace' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf();`n    $photoId = (int)($_POST['photo_id'] ?? 0);`n    if ($photoId <= 0) response(['success'=>false,'message'=>'Invalid photo'],422);`n    $stmt = $pdo->prepare('SELECT * FROM student_photos WHERE id=? LIMIT 1');`n    $stmt->execute([$photoId]);`n    $photo = $stmt->fetch();`n    if (!$photo) response(['success'=>false,'message'=>'Photo not found'],404);`n    if (!isset($_FILES['photo']) || $_FILES['photo']['error'] !== UPLOAD_ERR_OK)`n      response(['success'=>false,'message'=>'No photo selected or upload failed'],422);`n    $val = photoLibraryValidate($_FILES['photo']['tmp_name'], $_FILES['photo']['name']);`n    if ($val['ok'] !== true) response(['success'=>false,'message'=>$val['message']],422);`n    $studentId = (int)$photo['student_id'];`n    $pathInfo = photoStoragePath($studentId, $photo['type'] === 'PROCESSED' ? 'PROCESSED' : 'ORIGINAL', $val['ext']);`n    $destAbs = $pathInfo['dir'] . '/' . basename($pathInfo['rel']);`n    if (!move_uploaded_file($_FILES['photo']['tmp_name'], $destAbs))`n      response(['success'=>false,'message'=>'Failed to save photo'],500);`n    $relPath = 'uploads/' . $pathInfo['rel'];`n    /* Same row keeps its id/source/created_at so preferred-photo links stay`n     * valid; processing metadata is reset because the new file is a fresh`n     * upload (old background/crop no longer apply). */`n    $pdo->prepare('UPDATE student_photos SET file_path=?, mime_type=?, file_size=?, width=?, height=?, background_info=NULL, crop_data=NULL, processing_status="completed" WHERE id=?')`n        ->execute([$relPath, $val['mime'], filesize($destAbs), $val['w'], $val['h'], $photoId]);`n    $pdo->prepare('UPDATE id_cards SET photo_path=? WHERE preferred_photo_id=?')->execute([$relPath, $photoId]);`n    $old = photoSafePath($photo['file_path']);`n    if ($old && $old !== $destAbs && file_exists($old)) @unlink($old);`n    auditLog('PHOTO_REPLACED','student_photo',$photoId,['student_id'=>$studentId,'old_path'=>$photo['file_path']],['path'=>$relPath,'width'=>$val['w'],'height'=>$val['h']]);`n    response(['success'=>true,'message'=>'Photo replaced','photo_id'=>$photoId,'path'=>$relPath,'width'=>$val['w'],'height'=>$val['h']]);`n  }`n`n  /* --- Photo Library: search across all students --- */`n  if ($action==='photoLibrarySearch' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $filters = ['q'=>trim($_GET['q']??''),'id_type'=>trim($_GET['id_type']??''),'source'=>trim($_GET['source']??''),'type'=>trim($_GET['type']??''),'is_active'=>$_GET['is_active']??'','processing_status'=>trim($_GET['processing_status']??'')];`n    $page = max(1, (int)($_GET['page'] ?? 1));`n    $perPage = min(100, max(1, (int)($_GET['per_page'] ?? 20)));`n    $result = photoSearch($pdo, $filters, $page, $perPage);`n    response(['success'=>true,'data'=>$result['data'],'total'=>$result['total'],'page'=>$result['page'],'per_page'=>$result['per_page'],'total_pages'=>$result['total_pages']]);`n  }`n`n  /* --- Photo Library: serve file --- */`n  if ($action==='photoLibraryServe' && $_SERVER['REQUEST_METHOD']==='GET') {`n    photoServeFile($pdo, (int)($_GET['id'] ?? 0));`n  }`n`n  if ($action==='signatories' && $_SERVER['REQUEST_METHOD']==='GET') response(['success'=>true,'data'=>$pdo->query('SELECT * FROM signatories WHERE is_active=1 ORDER BY full_name')->fetchAll()]);`n    if ($action==='saveSignatory' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf(); $id=(int)($_POST['id']??0); $name=trim($_POST['full_name']??''); $position=trim($_POST['position_title']??''); if($name==='') response(['success'=>false,'message'=>'Signatory name is required'],422);`n    $path=uploadImage('signature','signatures') ?: trim($_POST['signature_path']??''); if($path==='') response(['success'=>false,'message'=>'Signature image is required'],422);`n    if($id){`n      $oldSig=auditFetchRow('signatories',$id);`n      $pdo->prepare('UPDATE signatories SET full_name=?,position_title=?,signature_path=? WHERE id=?')->execute([$name,$position,$path,$id]);`n      auditLog('signatory_updated','signatory',$id,$oldSig?['full_name'=>$oldSig['full_name'],'position_title'=>$oldSig['position_title'],'signature_path'=>$oldSig['signature_path']]:null,['full_name'=>$name,'position_title'=>$position,'signature_path'=>$path]);`n    }`n    else{`n      $pdo->prepare('INSERT INTO signatories(full_name,position_title,signature_path) VALUES(?,?,?)')->execute([$name,$position,$path]);$id=(int)$pdo->lastInsertId();`n      auditLog('signatory_created','signatory',$id,null,['full_name'=>$name,'position_title'=>$position,'signature_path'=>$path]);`n    }`n    response(['success'=>true,'id'=>$id]);`n  }`n  if ($action==='cards' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $search=trim($_GET['search']??''); $type=trim($_GET['type']??''); $sql='SELECT c.*, u.username AS released_by_name, (SELECT COUNT(*) FROM student_photos sp WHERE sp.student_id=c.id AND sp.is_active=1) AS photo_count FROM id_cards c LEFT JOIN users u ON u.id=c.released_by'; $where=[];$params=[];`n    if($search!==''){$where[]='(student_name LIKE ? OR student_number LIKE ? OR student_id_number LIKE ? OR lrn LIKE ? OR course LIKE ? OR grade_level LIKE ? OR section_name LIKE ?)';$like="%$search%";$params=array_merge($params,[$like,$like,$like,$like,$like,$like,$like]);}`n    if($type!==''){$where[]='id_type=?';$params[]=$type;}`n    if($where)$sql.=' WHERE '.implode(' AND ',$where); $sql.=' ORDER BY updated_at DESC'; $stmt=$pdo->prepare($sql);$stmt->execute($params);response(['success'=>true,'data'=>$stmt->fetchAll()]);`n  }`n  if ($action==='card' && $_SERVER['REQUEST_METHOD']==='GET') { $stmt=$pdo->prepare('SELECT c.*, u.username AS released_by_name, (SELECT COUNT(*) FROM student_photos sp WHERE sp.student_id=c.id AND sp.is_active=1) AS photo_count FROM id_cards c LEFT JOIN users u ON u.id=c.released_by WHERE c.id=?');$stmt->execute([(int)($_GET['id']??0)]);$row=$stmt->fetch();if(!$row)response(['success'=>false,'message'=>'Record not found'],404);response(['success'=>true,'data'=>$row]); }`n  /*`n   * Dashboard Analytics (GET, any authenticated staff/admin session).`n   * Returns aggregated counts computed entirely in SQL (GROUP BY / conditional`n   * SUMs) so the frontend never loads all records just to calculate totals.`n   * Filters (all optional): date_from / date_to (id_cards.created_at window),`n   * id_type (COLLEGE|JUNIOR_HIGH|SENIOR_HIGH) and status (card lifecycle).`n   * Metric sources:`n   *   - Total/Printed/Released/Per-department/Per-month: id_cards.`n   *     "Printed" = the card has been through the printer at least once`n   *     (print_count > 0, which stays true after release).`n   *   - Lost IDs: lost_id_requests (the lost-ID reprint request feature).`n   *   - Reprints: print_history rows with print_type='reprint' (print date`n   *     window), joined to id_cards so department/status filters still apply.`n   */`n  if ($action==='dashboardStats' && $_SERVER['REQUEST_METHOD']==='GET') {`n    requireLogin();`n    $from=trim($_GET['date_from']??''); $to=trim($_GET['date_to']??'');`n    $type=trim($_GET['id_type']??'');   $status=trim($_GET['status']??'');`n    if($type!=='' && !in_array($type,['COLLEGE','JUNIOR_HIGH','SENIOR_HIGH'],true)) $type='';`n    if($status!=='' && !in_array($status,['created','done','edited','printed','released'],true)) $status='';`n    $cardWhere=[];$cardParams=[];`n    if($from!==''&&strtotime($from)){$cardWhere[]='c.created_at>=?';$cardParams[]=date('Y-m-d 00:00:00',strtotime($from));}`n    if($to!==''&&strtotime($to)){$cardWhere[]='c.created_at<=?';$cardParams[]=date('Y-m-d 23:59:59',strtotime($to));}`n    if($type!==''){$cardWhere[]='c.id_type=?';$cardParams[]=$type;}`n    if($status!==''){$cardWhere[]='c.status=?';$cardParams[]=$status;}`n    $cardWhereSql=$cardWhere?'WHERE '.implode(' AND ',$cardWhere):'';`n    /* 1) Summary counters — one pass over the filtered card set. */`n    $s=$pdo->prepare("SELECT COUNT(*) AS total,`n        SUM(CASE WHEN c.print_count>0 THEN 1 ELSE 0 END) AS printed,`n        SUM(CASE WHEN c.status='released' THEN 1 ELSE 0 END) AS released,`n        SUM(CASE WHEN c.status IN ('created','done','edited') THEN 1 ELSE 0 END) AS in_progress`n      FROM id_cards c $cardWhereSql");`n    $s->execute($cardParams);`n    $summary=$s->fetch()?:[];`n    foreach(['total','printed','released','in_progress'] as $k) $summary[$k]=(int)($summary[$k]??0);`n`n    /* 2) Students/IDs by department (College / JHS / SHS). */`n    $s=$pdo->prepare("SELECT c.id_type, COUNT(*) AS total,`n        SUM(CASE WHEN c.print_count>0 THEN 1 ELSE 0 END) AS printed,`n        SUM(CASE WHEN c.status='released' THEN 1 ELSE 0 END) AS released`n      FROM id_cards c $cardWhereSql GROUP BY c.id_type");`n    $s->execute($cardParams);`n    $byTypeMap=[];`n    foreach($s->fetchAll() as $r) $byTypeMap[$r['id_type']]=['total'=>(int)$r['total'],'printed'=>(int)$r['printed'],'released'=>(int)$r['released']];`n    $byType=[];`n    foreach(['COLLEGE','JUNIOR_HIGH','SENIOR_HIGH'] as $t) $byType[]=['id_type'=>$t]+($byTypeMap[$t]??['total'=>0,'printed'=>0,'released'=>0]);`n    /* 3) Monthly ID generation: IDs created per month + IDs printed per month`n     * (print_history) for the bar/line chart. Both aggregated in SQL. */`n    $s=$pdo->prepare("SELECT DATE_FORMAT(c.created_at,'%Y-%m') AS ym, COUNT(*) AS n`n      FROM id_cards c $cardWhereSql GROUP BY ym ORDER BY ym");`n    $s->execute($cardParams);`n    $generated=[];`n    foreach($s->fetchAll() as $r) $generated[$r['ym']]=(int)$r['n'];`n    $printWhere=['1'];$printParams=[];`n    if($from!==''&&strtotime($from)){$printWhere[]='p.printed_at>=?';$printParams[]=date('Y-m-01 00:00:00',strtotime($from));}`n    if($to!==''&&strtotime($to)){$printWhere[]='p.printed_at<=?';$printParams[]=date('Y-m-t 23:59:59',strtotime($to));}`n    if($type!==''){$printWhere[]='c.id_type=?';$printParams[]=$type;}`n    if($status!==''){$printWhere[]='c.status=?';$printParams[]=$status;}`n    $s=$pdo->prepare("SELECT DATE_FORMAT(p.printed_at,'%Y-%m') AS ym, COUNT(*) AS n`n      FROM print_history p JOIN id_cards c ON c.id=p.card_id`n      WHERE ".implode(' AND ',$printWhere)."`n      GROUP BY ym ORDER BY ym");`n    $s->execute($printParams);`n    $printedMonthly=[];`n    foreach($s->fetchAll() as $r) $printedMonthly[$r['ym']]=(int)$r['n'];`n`n    /* 4) Lost IDs reported (lost_id_requests): date window on created_at,`n     * department filter applies; card-status filter does not (request rows`n     * carry their own pending/approved/reprinted/rejected lifecycle). */`n    $lostWhere=[];$lostParams=[];`n    if($from!==''&&strtotime($from)){$lostWhere[]='l.created_at>=?';$lostParams[]=date('Y-m-d 00:00:00',strtotime($from));}`n    if($to!==''&&strtotime($to)){$lostWhere[]='l.created_at<=?';$lostParams[]=date('Y-m-d 23:59:59',strtotime($to));}`n    if($type!==''){$lostWhere[]='l.id_type=?';$lostParams[]=$type;}`n    $lostWhereSql=$lostWhere?'WHERE '.implode(' AND ',$lostWhere):'';`n    $s=$pdo->prepare("SELECT COUNT(*) FROM lost_id_requests l $lostWhereSql");`n    $s->execute($lostParams);`n    $lost=(int)$s->fetchColumn();`n    /* 5) Reprint jobs: print_history reprints joined to id_cards so the`n     * department/status filters still apply; window is the print date. */`n    $rpWhere=['p.print_type=?'];$rpParams=['reprint'];`n    if($from!==''&&strtotime($from)){$rpWhere[]='p.printed_at>=?';$rpParams[]=date('Y-m-d 00:00:00',strtotime($from));}`n    if($to!==''&&strtotime($to)){$rpWhere[]='p.printed_at<=?';$rpParams[]=date('Y-m-d 23:59:59',strtotime($to));}`n    if($type!==''){$rpWhere[]='c.id_type=?';$rpParams[]=$type;}`n    if($status!==''){$rpWhere[]='c.status=?';$rpParams[]=$status;}`n    $s=$pdo->prepare('SELECT COUNT(*) FROM print_history p JOIN id_cards c ON c.id=p.card_id WHERE '.implode(' AND ',$rpWhere));`n    $s->execute($rpParams);`n    $reprints=(int)$s->fetchColumn();`n    response(['success'=>true,'data'=>[`n      'summary'=>$summary,`n      'by_type'=>$byType,`n      'monthly'=>['generated'=>$generated,'printed'=>$printedMonthly],`n      'lost_ids'=>$lost,`n      'reprints'=>$reprints,`n      'filters'=>['date_from'=>$from,'date_to'=>$to,'id_type'=>$type,'status'=>$status],`n    ]]);`n  }`n`n  if ($action==='saveCard' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $data=input(); $fields=['student_name','id_type','course','grade_level','section_name','student_number','student_id_number','lrn','academic_year','school_year','photo_path','preferred_photo_id','address_line1','address_line2','emergency_label','emergency_contact','emergency_phone','terms_title','term_1','term_2','term_3','institution_name','institution_address','mobile_no','telephone_no','email_address','signatory_id','signatory_name','signature_path','template_id','template_version','original_photo_path','photo_processing_status','photo_processed_at','photo_crop','background_mode','background_color'];`n    $values=[];foreach($fields as $f)$values[$f]=trim((string)($data[$f]??''));$id=(int)($data['id']??0);`n    /* Photo processing metadata (kept neutral when not provided) */`n    if (in_array($values['photo_processing_status']??'original',['original','processed','uploaded','failed'],true)===false) $values['photo_processing_status']='original';`n    /* Background mode validation */`n    if (!in_array($values['background_mode']??'transparent',['transparent','white','custom'],true)) $values['background_mode']='transparent';`n    /* Background color validation (must be a valid HEX color) */`n    if (!preg_match('/^#[0-9A-Fa-f]{6}$/',$values['background_color']??'')) $values['background_color']='#FFFFFF';`n    /* Normalise the UI's ISO-8601 photo_processed_at for the DATETIME column. */`n    $ppa=trim((string)($values['photo_processed_at']??''));`n    if ($ppa==='') { $values['photo_processed_at']=null; }`n    else { $ts=strtotime($ppa); $values['photo_processed_at']=$ts?date('Y-m-d H:i:s',$ts):null; }`n    /* Type-specific validation & mapping (shared helper; mirrors the UI rules) */`n    if ($err=normalizeCardByType($values)) response(['success'=>false,'message'=>$err['message']],$err['code']);`n    /* Serialize duplicate-check + write (same lock as the public path) */`n    $gotLock=(int)$pdo->query("SELECT GET_LOCK('lsc_card_write',10)")->fetchColumn();`n    if ($gotLock!==1) response(['success'=>false,'message'=>'Server is busy, please try again shortly'],503);`n    /* Duplicate prevention — parity with the public studentSaveCard path.`n     * Excludes the record being edited so updating a card never flags itself. */`n    $sn=trim((string)$values['student_number']); $sidn=trim((string)$values['student_id_number']); $lrnD=trim((string)$values['lrn']);`n    $dupCols=[];$dupParams=[];`n    if($sn!=='')  { $dupCols[]='student_number=?';    $dupParams[]=$sn; }`n    if($sidn!==''){ $dupCols[]='student_id_number=?'; $dupParams[]=$sidn; }`n    if($lrnD!==''){ $dupCols[]='lrn=?';               $dupParams[]=$lrnD; }`n    if($dupCols){`n      $dupParams=array_merge([$values['student_name']],$dupParams);`n      $dupSql='SELECT id FROM id_cards WHERE student_name=? AND ('.implode(' OR ',$dupCols).')';`n      if($id>0){ $dupSql.=' AND id<>?'; $dupParams[]=(int)$id; }`n      $dupSql.=' LIMIT 1';`n      $dupCheck=$pdo->prepare($dupSql);$dupCheck->execute($dupParams);`n      $dupRow=$dupCheck->fetch();`n      if($dupRow){`n        $pdo->query("SELECT RELEASE_LOCK('lsc_card_write')");`n        response(['success'=>false,'message'=>'A student with this name and student number/ID/LRN already exists.'],409);`n      }`n      /* no duplicate: KEEP holding the lock until after the write */`n    }`n    $curRow=null;`n    if($id){`n      /*`n       * ID status lifecycle: created -> done -> edited / printed.`n       * Editing a card that was already completed ("done") or already`n       * printed automatically flags it as "edited" so staff can see the`n       * ID changed after it was finalised / printed.`n       */`n      $cur=$pdo->prepare('SELECT * FROM id_cards WHERE id=?');$cur->execute([$id]);$curRow=$cur->fetch();`n      $curStatus=$curRow?trim((string)$curRow['status']):'created';`n      $newStatus=in_array($curStatus,['done','printed'],true)?'edited':($curStatus!==''?$curStatus:'created');`n      $values['status']=$newStatus;`n      $sets=implode(',',array_map(fn($f)=>"$f=:$f",$fields));`n      $values['id']=$id;$stmt=$pdo->prepare("UPDATE id_cards SET $sets, status=:status WHERE id=:id");$stmt->execute(cardBindValues($values,array_merge($fields,['status','id'])));`n    }else{`n      $values['status']='created';`n      $allFields=array_merge($fields,['status']);`n      $cols=implode(',',$allFields);$pars=implode(',',array_map(fn($f)=>":$f",$allFields));$stmt=$pdo->prepare("INSERT INTO id_cards($cols) VALUES($pars)");$stmt->execute(cardBindValues($values,$allFields));$id=(int)$pdo->lastInsertId();`n      $newStatus='created';`n    }`n    $pdo->query("SELECT RELEASE_LOCK('lsc_card_write')");`n    /* Audit: staff edit with structured field-level diff, or new card creation */`n    if ($id && $curRow) {`n      $diff=auditDiffFields($curRow,$values);`n      if ($diff) auditLog('card_updated','id_card',$id,array_intersect_key($curRow,$values),$diff);`n    } else {`n      auditLog('card_created','id_card',$id,null,['student_name'=>$values['student_name'],'student_number'=>$values['student_number'],'id_type'=>$values['id_type'],'status'=>'created']);`n    }`n    response([`n      'success'=>true,`n      'id'=>$id,`n      'status'=>$newStatus,`n      'message'=>($newStatus==='edited')`n        ? 'ID updated — status is now "Edited" (changed after completion/printing).'`n        : 'ID saved successfully (Status: Created).',`n    ]);`n  }`n  if ($action==='deleteCard' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d=input(); $cid=(int)($d['id']??0);`n    $oldCard=auditFetchRow('id_cards',$cid);`n    $pdo->prepare('DELETE FROM id_cards WHERE id=?')->execute([$cid]);`n    auditLog('card_deleted','id_card',$cid,$oldCard?['student_name'=>$oldCard['student_name'],'student_number'=>$oldCard['student_number'],'id_type'=>$oldCard['id_type'],'status'=>$oldCard['status']]:null,null);`n    response(['success'=>true]);`n  }`n  /*`n   * Quick student creation — creates a minimal id_cards record so photos`n   * can be uploaded to the Photo Library before the full ID is filled in.`n   * Used by the Photo Processing module "upload first" workflow.`n   */`n  if ($action==='quickCreateStudent' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d=input();`n    $name=trim((string)($d['student_name']??''));`n    $idType=trim((string)($d['id_type']??'COLLEGE'));`n    $idNumber=trim((string)($d['student_id_number']??''));`n    $lrn=trim((string)($d['lrn']??''));`n    $sectionName=trim((string)($d['section_name']??''));`n    if ($name==='') response(['success'=>false,'message'=>'Student name is required'],422);`n    if (!in_array($idType,['COLLEGE','JUNIOR_HIGH','SENIOR_HIGH'],true)) $idType='COLLEGE';`n    if ($lrn!=='' && !preg_match('/^\d{12}$/',$lrn)) response(['success'=>false,'message'=>'LRN must be exactly 12 digits'],422);`n    if ($idType==='COLLEGE') { $lrn=''; $sectionName=''; } // LRN + Section are Basic Education only`n    $defaultYear='2026-2027';`n    $signatories=[];`n    foreach($pdo->query('SELECT id,full_name,signature_path FROM signatories WHERE is_active=1') as $sig){`n      $signatories[$sig['full_name']]=['id'=>(int)$sig['id'],'path'=>$sig['signature_path']];`n    }`n    $sigName=$idType==='COLLEGE'?'Sherill S. Villaluz':'Annabelle V. Molina';`n    $sigId=null;$sigPath='';`n    if(isset($signatories[$sigName])){$sigId=$signatories[$sigName]['id'];$sigPath=$signatories[$sigName]['path'];}`n    $cols=['student_name','id_type','section_name','student_id_number','lrn','academic_year','school_year','signatory_id','signatory_name','signature_path','status'];`n    $vals=['student_name'=>$name,'id_type'=>$idType,'section_name'=>$sectionName,'student_id_number'=>$idNumber,'lrn'=>$lrn,'academic_year'=>$defaultYear,'school_year'=>$defaultYear,'signatory_id'=>$sigId,'signatory_name'=>$sigName,'signature_path'=>$sigPath,'status'=>'created'];`n    $colList=implode(',',$cols);`n    $parList=implode(',',array_map(fn($f)=>":$f",$cols));`n    $gotLock=(int)$pdo->query("SELECT GET_LOCK('lsc_card_write',10)")->fetchColumn();`n    if($gotLock!==1) response(['success'=>false,'message'=>'Server busy'],503);`n    $stmt=$pdo->prepare("INSERT INTO id_cards($colList) VALUES($parList)");`n    $stmt->execute($vals);`n    $newId=(int)$pdo->lastInsertId();`n    $pdo->query("SELECT RELEASE_LOCK('lsc_card_write')");`n    auditLog('student_quick_created','id_card',$newId,null,['student_name'=>$name,'id_type'=>$idType,'section_name'=>$sectionName,'student_id_number'=>$idNumber,'lrn'=>$lrn]);`n    response(['success'=>true,'id'=>$newId,'student_name'=>$name,'id_type'=>$idType,'message'=>'Student created. You can now upload photos.']);`n    }`n  /*`n   * ID status control.`n   *  - "done"    : admin marked the ID as completed / ready for printing`n   *  - "printed" : records the print job on the Smart ID 51 (timestamp + counter)`n   */`n  if ($action==='setCardStatus' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d=input(); $id=(int)($d['id']??0); $status=(string)($d['status']??'');`n    $allowed=['created','done','edited','printed'];`n    if($id<=0||!in_array($status,$allowed,true)) response(['success'=>false,'message'=>'Invalid card id or status'],422);`n    /* Audit: capture the PREVIOUS row BEFORE the update so old_value is correct */`n    $oldCard=auditFetchRow('id_cards',$id);`n    /* Released IDs are terminal — no further status transitions */`n    if($oldCard && ($oldCard['status']??'')==='released') response(['success'=>false,'message'=>'This ID has already been released and can no longer change status.'],409);`n    if($status==='printed'){`n      $pdo->prepare("UPDATE id_cards SET status='printed', printed_at=NOW(), print_count=print_count+1 WHERE id=?")->execute([$id]);`n    }else{`n      $pdo->prepare('UPDATE id_cards SET status=? WHERE id=?')->execute([$status,$id]);`n    }`n    $stmt=$pdo->prepare('SELECT id,status,printed_at,print_count FROM id_cards WHERE id=?');$stmt->execute([$id]);`n    $newRow=$stmt->fetch();`n    auditLog($status==='printed'?'card_printed':'card_status_changed','id_card',$id,['status'=>$oldCard['status']??null],$newRow);`n    response(['success'=>true,'data'=>$newRow,'message'=>'Status updated']);`n  }`n  /*`n   * Print History — records EVERY print job (printCard, POST, CSRF-protected).`n   *  - 1st print of an ID -> print_type='original' (reason defaults to "New Student")`n   *  - any later print    -> print_type='reprint'  (reason REQUIRED: Damaged /`n   *    Lost / Incorrect Information / Other — free text allowed, max 255 chars)`n   * Keeps id_cards.status/printed_at/print_count in sync in the SAME`n   * transaction (legacy consumers depend on them) and appends one immutable`n   * print_history row. Released IDs are terminal and cannot be printed.`n   */`n  if ($action==='printCard' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d=input(); $id=(int)($d['id']??0);`n    $reason=trim((string)($d['reason']??''));`n    if($id<=0) response(['success'=>false,'message'=>'Invalid card id'],422);`n    $oldCard=auditFetchRow('id_cards',$id);`n    if(!$oldCard) response(['success'=>false,'message'=>'Record not found'],404);`n    if(($oldCard['status']??'')==='released') response(['success'=>false,'message'=>'This ID has already been released and can no longer be printed.'],409);`n    /* Original vs Reprint is derived server-side (never trusted from the client) */`n    $printType=((int)($oldCard['print_count']??0)===0 && ($oldCard['printed_at']??null)===null)?'original':'reprint';`n    if($printType==='reprint' && $reason==='')`n      response(['success'=>false,'message'=>'A reason is required for a reprint (Damaged, Lost, Incorrect Information or Other).'],422);`n    if(mb_strlen($reason)>255) response(['success'=>false,'message'=>'Reason is too long (max 255 characters)'],422);`n    if($printType==='original' && $reason==='') $reason='New Student';`n    $me=currentUser();`n    try{`n      $pdo->beginTransaction();`n      $pdo->prepare("UPDATE id_cards SET status='printed', printed_at=NOW(), print_count=print_count+1 WHERE id=?")->execute([$id]);`n      /* photo_id records the exact photo used (2026_09_14 migration) — the`n       * column was added to this INSERT without its value, which made every`n       * print fail with a bound-variable mismatch. */`n      $photoId=((int)($oldCard['preferred_photo_id']??0))?:null;`n      $pdo->prepare('INSERT INTO print_history(card_id,photo_id,user_id,print_type,reason,printed_at) VALUES(?,?,?,?,?,NOW())')`n        ->execute([$id,$photoId,(int)($me['id']??0),$printType,$reason]);`n      $phId=(int)$pdo->lastInsertId();`n      $pdo->commit();`n    }catch(Throwable $e){`n      if($pdo->inTransaction())$pdo->rollBack();`n      response(['success'=>false,'message'=>'Could not record the print job. '.$e->getMessage()],500);`n    }`n    $stmt=$pdo->prepare('SELECT id,status,printed_at,print_count FROM id_cards WHERE id=?');$stmt->execute([$id]);`n    $newRow=$stmt->fetch();`n    /* Audit: "Staff printed Student ID" — enriched with type + reason */`n    auditLog('card_printed','id_card',$id,`n      ['status'=>$oldCard['status']??null,'print_count'=>(int)($oldCard['print_count']??0)],`n      ['status'=>'printed','student_name'=>$oldCard['student_name']??null,'printed_at'=>$newRow['printed_at']??null,'print_count'=>(int)($newRow['print_count']??0),'print_type'=>$printType,'reason'=>$reason]);`n    response(['success'=>true,'data'=>$newRow,'print_type'=>$printType,'reason'=>$reason,'print_history_id'=>$phId,`n      'message'=>$printType==='reprint'?'Reprint recorded — print history updated.':'Print recorded — print history updated.']);`n  }`n  /*`n   * Batch Printing (bulkPrint, POST, CSRF-protected).`n   * Prints several IDs in ONE Smart ID 51 job from the Records screen and`n   * routes EVERY card through the same tracking as the single-card print:`n   *   - one print_history row per ID (user, print_type, reason, timestamp)`n   *   - id_cards.status/printed_at/print_count kept in sync in the SAME`n   *     transaction (legacy consumers depend on them)`n   *   - released IDs are terminal and are SKIPPED, never re-printed`n   *   - Original vs Reprint is derived server-side per card (never trusted`n   *     from the client); a batch containing any already-printed ID REQUIRES`n   *     a reason (Damaged / Lost / Incorrect Information / Other), first`n   *     prints default to "New Student"`n   * Audit: one card_printed row per ID (flagged bulk) plus a single`n   * bulk_ids_printed summary row with user, count and every ID/student.`n   */`n  if ($action==='bulkPrint' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireLogin(); verifyCsrf(); $d=input();`n    $ids=$d['ids']??'';`n    if(!is_array($ids)) response(['success'=>false,'message'=>'No IDs selected for printing.'],422);`n    $ids=array_values(array_unique(array_filter(array_map('intval',$ids),fn($v)=>$v>0)));`n    if(!$ids) response(['success'=>false,'message'=>'No valid IDs were selected for printing.'],422);`n    if(count($ids)>200) response(['success'=>false,'message'=>'Too many IDs in one batch (max 200). Please print in smaller batches.'],422);`n    $reason=trim((string)($d['reason']??''));`n    if(mb_strlen($reason)>255) response(['success'=>false,'message'=>'Reason is too long (max 255 characters)'],422);`n    /* Load every requested card once, then classify:`n     * printable / skipped (released) / missing (unknown id). */`n    $in=implode(',',array_fill(0,count($ids),'?'));`n    $st=$pdo->prepare("SELECT * FROM id_cards WHERE id IN ($in)");`n    $st->execute($ids);`n    $byId=[];`n    foreach($st->fetchAll() as $r) $byId[(int)$r['id']]=$r;`n    $todo=[];$skipped=[];$missing=[];`n    foreach($ids as $id){`n      if(!isset($byId[$id])){ $missing[]=['id'=>$id]; continue; }`n      $c=$byId[$id];`n      if(($c['status']??'')==='released'){`n        $skipped[]=['id'=>$id,'student_name'=>$c['student_name']??null,'reason'=>'Released IDs can no longer be printed'];`n        continue;`n      }`n      $todo[]=$c;`n    }`n    if(!$todo) response(['success'=>false,'message'=>'None of the selected IDs can be printed.','data'=>['printed'=>0,'skipped'=>$skipped,'missing'=>$missing]],422);`n    /* Reprint reason: required when the batch contains ANY already-printed ID */`n    $hasReprint=false;`n    foreach($todo as $c){ if(!((int)($c['print_count']??0)===0 && ($c['printed_at']??null)===null)){ $hasReprint=true; break; } }`n    if($hasReprint && $reason==='')`n      response(['success'=>false,'message'=>'A reason is required: the batch contains IDs that were printed before (Damaged, Lost, Incorrect Information or Other).'],422);`n    if(!$hasReprint && $reason==='') $reason='New Student';`n    $me=currentUser();`n    $printedRows=[];`n    try{`n      $pdo->beginTransaction();`n      $upd=$pdo->prepare("UPDATE id_cards SET status='printed', printed_at=NOW(), print_count=print_count+1 WHERE id=? AND status<>'released'");`n      $ins=$pdo->prepare('INSERT INTO print_history(card_id,photo_id,user_id,print_type,reason,printed_at) VALUES(?,?,?,?,?,NOW())');`n      foreach($todo as $c){`n        $cid=(int)$c['id'];`n        $printType=((int)($c['print_count']??0)===0 && ($c['printed_at']??null)===null)?'original':'reprint';`n        $cardReason=$printType==='reprint'?$reason:'New Student';`n        $upd->execute([$cid]);`n        if($upd->rowCount()===0){`n          /* The card became released concurrently — abort without recording`n           * anything so no ID is marked printed unless the row was updated. */`n          $pdo->rollBack();`n          response(['success'=>false,'message'=>'One of the selected IDs changed while printing. Please review the batch and try again.'],409);`n        }`n        $ins->execute([$cid,((int)($c['preferred_photo_id']??0))?:null,(int)($me['id']??0),$printType,$cardReason]);`n        $printedRows[]=['id'=>$cid,'print_history_id'=>(int)$pdo->lastInsertId(),'student_name'=>$c['student_name']??null,'id_type'=>$c['id_type']??null,'print_type'=>$printType,'reason'=>$cardReason,'old_status'=>$c['status']??null,'old_print_count'=>(int)($c['print_count']??0)];`n      }`n      $pdo->commit();`n    }catch(Throwable $e){`n      if($pdo->inTransaction())$pdo->rollBack();`n      response(['success'=>false,'message'=>'Could not record the print jobs. '.$e->getMessage()],500);`n    }`n    /* Audit: per-ID card_printed rows keep the audit trail identical to`n     * single prints; the summary row records the bulk action as one event`n     * (user + count + every ID/student included + timestamp via created_at). */`n    foreach($printedRows as $p){`n      auditLog('card_printed','id_card',$p['id'],`n        ['status'=>$p['old_status'],'print_count'=>$p['old_print_count']],`n        ['status'=>'printed','student_name'=>$p['student_name'],'print_type'=>$p['print_type'],'reason'=>$p['reason'],'bulk_print'=>true]);`n    }`n    auditLog('bulk_ids_printed','id_card',null,null,[`n      'batch_print'=>true,`n      'count'=>count($printedRows),`n      'reason'=>$reason,`n      'ids'=>$printedRows,`n      'skipped'=>$skipped,`n      'user'=>$me['username']??null,`n    ]);`n    response(['success'=>true,'data'=>[`n      'printed'=>count($printedRows),`n      'skipped'=>$skipped,`n      'missing'=>$missing,`n      'details'=>$printedRows,`n    ],'message'=>count($printedRows).' ID(s) printed and recorded in the Print History.'`n      .($skipped?' '.count($skipped).' skipped (released).':'')`n      .($missing?' '.count($missing).' not found.':'')]);`n  }`n  /*`n   * Released ID status: PRINTED -> RELEASED (staff/admin, CSRF-protected).`n   * Only an ID that has actually been printed may be released; a released ID`n   * cannot be released again. Records who released it, when, optional notes`n   * and whether the student physically received the card. Audited.`n   */`n  if ($action==='releaseCard' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d=input(); $id=(int)($d['id']??0);`n    if($id<=0) response(['success'=>false,'message'=>'Invalid card id'],422);`n    $oldCard=auditFetchRow('id_cards',$id);`n    if(!$oldCard) response(['success'=>false,'message'=>'Record not found'],404);`n    if(($oldCard['status']??'')==='released') response(['success'=>false,'message'=>'This ID has already been released.'],409);`n    if(($oldCard['status']??'')!=='printed' && ($oldCard['printed_at']??null)===null)`n      response(['success'=>false,'message'=>'Only a printed ID can be released.'],422);`n    $notes=trim((string)($d['release_notes']??''));`n    if(strlen($notes)>1000) response(['success'=>false,'message'=>'Release notes are too long (max 1000 characters)'],422);`n    $received=!empty($d['student_received'])?1:0;`n    $me=currentUser();`n    $pdo->prepare("UPDATE id_cards SET status='released', released_by=?, released_at=NOW(), release_notes=?, student_received=? WHERE id=?")`n      ->execute([(int)($me['id']??0),$notes,$received,$id]);`n    $stmt=$pdo->prepare('SELECT c.*, u.username AS released_by_name, (SELECT COUNT(*) FROM student_photos sp WHERE sp.student_id=c.id AND sp.is_active=1) AS photo_count FROM id_cards c LEFT JOIN users u ON u.id=c.released_by WHERE c.id=?');`n    $stmt->execute([$id]);`n    $newRow=$stmt->fetch();`n    auditLog('card_released','id_card',$id,`n      ['status'=>$oldCard['status']??null],`n      ['status'=>'released','released_by_name'=>$newRow['released_by_name']??null,'released_at'=>$newRow['released_at']??null,'release_notes'=>$notes!==''?$notes:null,'student_received'=>$received]);`n    response(['success'=>true,'data'=>$newRow,'message'=>'ID released']);`n  }`n  /* ===== ID Template module ===== */`n  if ($action==='templates' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $rows=$pdo->query("SELECT * FROM id_templates ORDER BY FIELD(id_type,'COLLEGE','JUNIOR_HIGH','SENIOR_HIGH'), is_system DESC, updated_at DESC")->fetchAll();`n    foreach($rows as &$r){ $r['fields_json']=($r['fields_json']??'')?json_decode($r['fields_json'],true):[]; }`n    response(['success'=>true,'data'=>$rows]);`n  }`n  if ($action==='saveTemplate' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf();`n    $id=(int)($_POST['id']??0);`n    $name=trim((string)($_POST['name']??''));`n`n    /* System templates (the built-in Original LSC Design) are protected. */`n    if ($id>0) {`n      $sv=$pdo->prepare('SELECT id,name,id_type,is_active,is_system FROM id_templates WHERE id=?');`n      $sv->execute([$id]);`n      $existing=$sv->fetch();`n      if ($existing && (int)$existing['is_system']===1) {`n        response(['success'=>false,'message'=>'The Original LSC Design is a protected system template and cannot be edited or deleted.'],403);`n      }`n    }`n`n    $idType=trim((string)($_POST['id_type']??''));`n    if($name==='') response(['success'=>false,'message'=>'Template name is required'],422);`n    if(!in_array($idType,['COLLEGE','JUNIOR_HIGH','SENIOR_HIGH'],true)) $idType='COLLEGE';`n    $ppm=trim((string)($_POST['photo_processing_mode']??'ORIGINAL'));`n    if(!in_array($ppm,['ORIGINAL','TRANSPARENT'],true)) $ppm='ORIGINAL';`n    $fieldsRaw=trim((string)($_POST['fields_json']??'[]'));`n    $fieldsArr=json_decode($fieldsRaw,true);`n    if(!is_array($fieldsArr)) $fieldsArr=[];`n    $front=uploadImage('front_image','templates');`n    $back=uploadImage('back_image','templates');`n    $prevFront=trim((string)($_POST['front_image_prev']??''));`n    $prevBack=trim((string)($_POST['back_image_prev']??''));`n    if($front==='') $front=$prevFront;`n    if($back==='') $back=$prevBack;`n    if($id===0 && $front==='') response(['success'=>false,'message'=>'Please upload the FRONT design image (PNG or JPG) of the template'],422);`n    $isActive=isset($_POST['is_active'])&&(string)($_POST['is_active'])==='1'?1:0;`n    if($isActive){ $pdo->prepare('UPDATE id_templates SET is_active=0 WHERE id_type=?')->execute([$idType]); }`n    $json=json_encode($fieldsArr,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);`n    if($id){`n      $pdo->prepare('UPDATE id_templates SET name=?,id_type=?,front_image=?,back_image=?,fields_json=?,photo_processing_mode=?,is_active=? WHERE id=?')`n        ->execute([$name,$idType,$front,$back,$json,$ppm,$isActive,$id]);`n      auditLog('template_updated','id_template',$id,isset($existing)?['name'=>$existing['name'],'id_type'=>$existing['id_type'],'is_active'=>(int)$existing['is_active']]:null,['name'=>$name,'id_type'=>$idType,'photo_processing_mode'=>$ppm,'is_active'=>$isActive]);`n    }else{`n      $pdo->prepare('INSERT INTO id_templates(name,id_type,front_image,back_image,fields_json,photo_processing_mode,is_active) VALUES(?,?,?,?,?,?,?)')`n        ->execute([$name,$idType,$front,$back,$json,$ppm,$isActive]);`n      $id=(int)$pdo->lastInsertId();`n      auditLog('template_created','id_template',$id,null,['name'=>$name,'id_type'=>$idType,'photo_processing_mode'=>$ppm,'is_active'=>$isActive]);`n    }`n    response(['success'=>true,'id'=>$id,'message'=>'Template saved successfully']);`n  }`n  if ($action==='setActiveTemplate' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf(); $d=input();`n    $id=(int)($d['id']??0);`n    $sv=$pdo->prepare('SELECT id_type FROM id_templates WHERE id=?');`n    $sv->execute([$id]);`n    $row=$sv->fetch();`n    if(!$row) response(['success'=>false,'message'=>'Template not found'],404);`n    $pv=$pdo->prepare('SELECT id FROM id_templates WHERE id_type=? AND is_active=1');$pv->execute([$row['id_type']]);$prevActive=$pv->fetch();`n    $pdo->prepare('UPDATE id_templates SET is_active=0 WHERE id_type=?')->execute([$row['id_type']]);`n    $pdo->prepare('UPDATE id_templates SET is_active=1 WHERE id=?')->execute([$id]);`n    auditLog('template_activated','id_template',$id,['previous_active_id'=>$prevActive?(int)$prevActive['id']:null],['id_type'=>$row['id_type']]);`n    response(['success'=>true,'message'=>'Template set as active']);`n  }`n  if ($action==='deleteTemplate' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf(); $d=input();`n    $id=(int)($d['id']??0);`n    $sv=$pdo->prepare('SELECT is_system,name FROM id_templates WHERE id=?');`n    $sv->execute([$id]);`n    $existing=$sv->fetch();`n    if ($existing && (int)$existing['is_system']===1) {`n      response(['success'=>false,'message'=>'The Original LSC Design is a protected system template and cannot be deleted.'],403);`n    }`n    $pdo->prepare('DELETE FROM id_templates WHERE id=?')->execute([$id]);`n    auditLog('template_deleted','id_template',$id,['name'=>$existing['name']??null],null);`n    response(['success'=>true,'message'=>'Template deleted']);`n  }`n  if ($action==='lostIdRequests' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $status=trim($_GET['status']??'');`n    if ($status!=='') {`n      $stmt=$pdo->prepare("SELECT * FROM lost_id_requests WHERE status=? ORDER BY FIELD(status,'pending','approved','reprinted','rejected'), updated_at DESC");`n      $stmt->execute([$status]);`n    } else {`n      $stmt=$pdo->query("SELECT * FROM lost_id_requests ORDER BY FIELD(status,'pending','approved','reprinted','rejected'), updated_at DESC");`n    }`n    response(['success'=>true,'data'=>$stmt->fetchAll()]);`n  }`n  if ($action==='lostIdRequest' && $_SERVER['REQUEST_METHOD']==='GET') {`n    $stmt=$pdo->prepare('SELECT * FROM lost_id_requests WHERE id=?');`n    $stmt->execute([(int)($_GET['id']??0)]);`n    $row=$stmt->fetch();`n    if (!$row) response(['success'=>false,'message'=>'Request not found'],404);`n    response(['success'=>true,'data'=>$row]);`n  }`n  if ($action==='updateLostIdRequest' && $_SERVER['REQUEST_METHOD']==='POST') {`n    verifyCsrf(); $d=input();`n    $id=(int)($d['id']??0);`n    if ($id<=0) response(['success'=>false,'message'=>'Invalid request id'],422);`n    $updates=[];$values=[];`n    $allowedStatus=['pending','approved','reprinted','rejected'];`n    if (isset($d['status']) && in_array($d['status'],$allowedStatus,true)) { $updates[]='status=?'; $values[]=$d['status']; }`n    if (isset($d['reference_card_id'])) { $updates[]='reference_card_id=?'; $values[]=(int)$d['reference_card_id']; }`n    if (array_key_exists('notes',$d)) { $updates[]='notes=?'; $values[]=trim((string)$d['notes']); }`n    if (!$updates) response(['success'=>false,'message'=>'Nothing to update'],422);`n    $oldReq=auditFetchRow('lost_id_requests',$id);`n    $values[]=$id;`n    $pdo->prepare('UPDATE lost_id_requests SET '.implode(',',$updates).' WHERE id=?')->execute($values);`n    auditLog(isset($d['status'])&&$d['status']==='approved'?'lost_id_approved':'lost_id_updated','lost_id_request',$id,`n      $oldReq?['status'=>$oldReq['status'],'notes'=>$oldReq['notes'],'reference_card_id'=>(int)$oldReq['reference_card_id']]:null,`n      ['status'=>$d['status']??($oldReq['status']??null),'notes'=>array_key_exists('notes',$d)?trim((string)$d['notes']):($oldReq['notes']??null),'reference_card_id'=>isset($d['reference_card_id'])?(int)$d['reference_card_id']:($oldReq['reference_card_id']??null)]);`n    response(['success'=>true,'message'=>'Request updated successfully']);`n  }`n  if ($action==='deleteLostIdRequest' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf(); $d=input();`n    $oldReq=auditFetchRow('lost_id_requests',(int)($d['id']??0));`n    $pdo->prepare('DELETE FROM lost_id_requests WHERE id=?')->execute([(int)($d['id']??0)]);`n    auditLog('lost_id_deleted','lost_id_request',(int)($d['id']??0),$oldReq?['student_name'=>$oldReq['student_name'],'status'=>$oldReq['status']]:null,null);`n    response(['success'=>true,'message'=>'Request removed']);`n  }`n  if ($action==='users' && $_SERVER['REQUEST_METHOD']==='GET') {`n    requireAdmin();`n    response(['success'=>true,'data'=>$pdo->query('SELECT id,username,full_name,role,is_active,created_at FROM users ORDER BY id')->fetchAll()]);`n  }`n  /*`n  | Audit Logs (admin-only, read-only). Server-side pagination + filters.`n  | Users can never create, edit or delete log rows through the API:`n  | rows are only ever INSERTed by auditLog() inside audited actions.`n  */`n  if ($action==='auditLogs' && $_SERVER['REQUEST_METHOD']==='GET') {`n    requireAdmin();`n    $search=trim($_GET['search']??''); $actFilter=trim($_GET['action_type']??''); $userFilter=trim($_GET['user_id']??'');`n    $from=trim($_GET['date_from']??''); $to=trim($_GET['date_to']??'');`n    $page=max(1,(int)($_GET['page']??1)); $perPage=min(100,max(5,(int)($_GET['per_page']??15)));`n    $where=[];$params=[];`n    if($search!==''){`n      $where[]='(a.action LIKE ? OR a.entity_type LIKE ? OR a.entity_id=? OR a.old_value LIKE ? OR a.new_value LIKE ? OR u.username LIKE ? OR u.full_name LIKE ?)';`n      $like="%$search%";`n      array_push($params,$like,$like,ctype_digit($search)?(int)$search:0,$like,$like,$like,$like);`n    }`n    if($actFilter!==''){$where[]='a.action=?';$params[]=$actFilter;}`n    if($userFilter!==''){$where[]='a.user_id=?';$params[]=(int)$userFilter;}`n    if($from!==''&&strtotime($from)){$where[]='a.created_at>=?';$params[]=date('Y-m-d 00:00:00',strtotime($from));}`n    if($to!==''&&strtotime($to)){$where[]='a.created_at<=?';$params[]=date('Y-m-d 23:59:59',strtotime($to));}`n    $whereSql=$where?'WHERE '.implode(' AND ',$where):'';`n    $c=$pdo->prepare("SELECT COUNT(*) FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id $whereSql");$c->execute($params);$total=(int)$c->fetchColumn();`n    $totalPages=max(1,(int)ceil($total/$perPage));$page=min($page,$totalPages);`n    $off=($page-1)*$perPage;`n    $s=$pdo->prepare("SELECT a.*,u.username,u.full_name,u.role AS user_role FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id $whereSql ORDER BY a.id DESC LIMIT $perPage OFFSET $off");`n    $s->execute($params);`n    $acts=$pdo->query('SELECT DISTINCT action FROM audit_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN);`n    response(['success'=>true,'data'=>$s->fetchAll(),'pagination'=>['page'=>$page,'per_page'=>$perPage,'total'=>$total,'total_pages'=>$totalPages],'actions'=>$acts]);`n  }`n  /*`n   * Print History (admin-only, read-only). Every print job recorded by the`n   * printCard action: when, which student, who printed it, Original/Reprint`n   * and the reason. Server-side pagination + search / user / type / date`n   * filters, plus report totals (prints this month, original vs reprint and`n   * how many IDs each staff member printed). Rows are never editable or`n   * deletable through the API.`n   */`n  if ($action==='printHistory' && $_SERVER['REQUEST_METHOD']==='GET') {`n    requireAdmin();`n    $search=trim($_GET['search']??''); $typeFilter=trim($_GET['type']??''); $userFilter=trim($_GET['user_id']??'');`n    $from=trim($_GET['date_from']??''); $to=trim($_GET['date_to']??'');`n    $page=max(1,(int)($_GET['page']??1)); $perPage=min(100,max(5,(int)($_GET['per_page']??15)));`n    $where=[];$params=[];`n    if($search!==''){`n      $where[]='(c.student_name LIKE ? OR c.student_number LIKE ? OR c.student_id_number LIKE ? OR c.lrn LIKE ? OR p.reason LIKE ? OR u.username LIKE ? OR u.full_name LIKE ?)';`n      $like="%$search%";`n      array_push($params,$like,$like,$like,$like,$like,$like,$like);`n    }`n    if($typeFilter!=='' && in_array($typeFilter,['original','reprint'],true)){$where[]='p.print_type=?';$params[]=$typeFilter;}`n    if($userFilter!==''){$where[]='p.user_id=?';$params[]=(int)$userFilter;}`n    if($from!==''&&strtotime($from)){$where[]='p.printed_at>=?';$params[]=date('Y-m-d 00:00:00',strtotime($from));}`n    if($to!==''&&strtotime($to)){$where[]='p.printed_at<=?';$params[]=date('Y-m-d 23:59:59',strtotime($to));}`n    $whereSql=$where?'WHERE '.implode(' AND ',$where):'';`n    $c=$pdo->prepare("SELECT COUNT(*) FROM print_history p LEFT JOIN id_cards c ON c.id=p.card_id LEFT JOIN users u ON u.id=p.user_id $whereSql");`n    $c->execute($params);$total=(int)$c->fetchColumn();`n    $totalPages=max(1,(int)ceil($total/$perPage));$page=min($page,$totalPages);`n    $off=($page-1)*$perPage;`n    $s=$pdo->prepare("SELECT p.*,c.student_name,c.student_number,c.student_id_number,c.id_type,u.username,u.full_name,u.role AS user_role FROM print_history p LEFT JOIN id_cards c ON c.id=p.card_id LEFT JOIN users u ON u.id=p.user_id $whereSql ORDER BY p.printed_at DESC, p.id DESC LIMIT $perPage OFFSET $off");`n    $s->execute($params);`n    /* Report totals: "How many IDs were printed this month?", "original vs`n     * reprints?" and "how many IDs did each staff member print?" */`n    $monthStart=date('Y-m-01 00:00:00');`n    $m=$pdo->prepare('SELECT print_type,COUNT(*) AS n FROM print_history WHERE printed_at>=? GROUP BY print_type');`n    $m->execute([$monthStart]);`n    $month=['total'=>0,'original'=>0,'reprint'=>0];`n    foreach($m->fetchAll() as $r){$month[$r['print_type']]=(int)$r['n'];$month['total']+=(int)$r['n'];}`n    $byUser=$pdo->prepare('SELECT u.id,u.username,u.full_name,u.role,SUM(CASE WHEN p.printed_at>=? THEN 1 ELSE 0 END) AS month_count,COUNT(*) AS total_count FROM print_history p JOIN users u ON u.id=p.user_id GROUP BY u.id,u.username,u.full_name,u.role ORDER BY total_count DESC, u.username');`n    $byUser->execute([$monthStart]);`n    response(['success'=>true,'data'=>$s->fetchAll(),'pagination'=>['page'=>$page,'per_page'=>$perPage,'total'=>$total,'total_pages'=>$totalPages],'summary'=>['month'=>$month,'by_user'=>$byUser->fetchAll()]]);`n  }`n  if ($action==='saveUser' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf(); $d=input();`n    $id=(int)($d['id']??0); $username=trim((string)($d['username']??'')); $fullName=trim((string)($d['full_name']??''));`n    $role=($d['role']??'staff')==='admin'?'admin':'staff'; $password=(string)($d['password']??'');`n    $isActive=isset($d['is_active'])?((int)(bool)$d['is_active']):1;`n    if($username===''||$fullName==='') response(['success'=>false,'message'=>'Username and full name are required'],422);`n    if($password!==''&&strlen($password)<6) response(['success'=>false,'message'=>'Password must be at least 6 characters'],422);`n    if(!$id&&$password==='') response(['success'=>false,'message'=>'Password is required for new users'],422);`n    $dup=$pdo->prepare('SELECT id FROM users WHERE username=? AND id<>? LIMIT 1');$dup->execute([$username,$id]);`n    if($dup->fetch()) response(['success'=>false,'message'=>'That username is already taken'],422);`n    if($id===(int)$_SESSION['user_id']){$isActive=1;$role='admin';}`n    if($id){`n      $oldUser=auditFetchRow('users',$id);`n      if($password!==''){$pdo->prepare('UPDATE users SET username=?,full_name=?,role=?,is_active=?,password=? WHERE id=?')->execute([$username,$fullName,$role,$isActive,password_hash($password,PASSWORD_DEFAULT),$id]);}`n      else{$pdo->prepare('UPDATE users SET username=?,full_name=?,role=?,is_active=? WHERE id=?')->execute([$username,$fullName,$role,$isActive,$id]);}`n      /* Audit (passwords are never logged) */`n      $disabling=((int)($oldUser['is_active']??1)===1 && $isActive===0);`n      auditLog($disabling?'user_disabled':'user_updated','user',$id,$oldUser?['username'=>$oldUser['username'],'full_name'=>$oldUser['full_name'],'role'=>$oldUser['role'],'is_active'=>(int)$oldUser['is_active']]:null,['username'=>$username,'full_name'=>$fullName,'role'=>$role,'is_active'=>$isActive]);`n    }else{`n      $pdo->prepare('INSERT INTO users(username,password,full_name,role,is_active) VALUES(?,?,?,?,1)')->execute([$username,password_hash($password,PASSWORD_DEFAULT),$fullName,$role]);`n      $id=(int)$pdo->lastInsertId();`n      auditLog('user_created','user',$id,null,['username'=>$username,'full_name'=>$fullName,'role'=>$role,'is_active'=>1]);`n    }`n    response(['success'=>true,'id'=>$id,'message'=>'User saved successfully']);`n  }`n  if ($action==='deleteUser' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf(); $d=input(); $id=(int)($d['id']??0);`n    if($id===(int)$_SESSION['user_id']) response(['success'=>false,'message'=>'You cannot deactivate your own account'],422);`n    $oldUser=auditFetchRow('users',$id);`n    $pdo->prepare('UPDATE users SET is_active=0 WHERE id=?')->execute([$id]);`n    auditLog('user_disabled','user',$id,$oldUser?['username'=>$oldUser['username'],'is_active'=>(int)$oldUser['is_active']]:['is_active'=>1],['is_active'=>0]);`n    response(['success'=>true,'message'=>'User deactivated']);`n  }`n  /* CSV / Excel Student Import */`n  if ($action==='importTemplate' && $_SERVER['REQUEST_METHOD']==='GET') { requireLogin(); while (ob_get_level() > 0) ob_end_clean(); importSendTemplate(); return; }`n  if ($action==='importUpload' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireLogin(); verifyCsrf();`n    if(!isset($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK) response(['success'=>false,'message'=>'No file uploaded or upload error'],422);`n    $file=$_FILES['file']; $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));`n    if(!in_array($ext,['csv','xlsx','xls'],true)) response(['success'=>false,'message'=>'Only .csv, .xlsx and .xls files are allowed'],422);`n    if($file['size']>IMPORT_MAX_FILE_BYTES) response(['success'=>false,'message'=>'File is too large (max 10 MB)'],422);`n    try{`n      $parsed=match($ext){'csv'=>importParseCsv($file['tmp_name']),'xlsx'=>importParseXlsx($file['tmp_name']),'xls'=>importParseXls($file['tmp_name'])};`n      [$collected,$sheetErrors]=importCollectRows($parsed);`n      $result=importValidateRows($pdo,$collected);`n      response(['success'=>true,'data'=>$result]);`n    }catch(Throwable $e){response(['success'=>false,'message'=>$e->getMessage()],422);}`n  }`n  if ($action==='importCommit' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireLogin(); verifyCsrf(); $d=input();`n    $rows=$d['rows']??[];`n    if(!is_array($rows)||empty($rows)) response(['success'=>false,'message'=>'No rows to import'],422);`n    try{`n      $ids=importCommitRows($pdo,$rows);`n      auditLog('students_imported','id_card',null,null,['count'=>count($ids),'ids'=>$ids]);`n      response(['success'=>true,'imported'=>count($ids),'ids'=>$ids,'message'=>count($ids).' students imported successfully']);`n        }catch(Throwable $e){response(['success'=>false,'message'=>$e->getMessage()],500);}`n  }`n  if ($action==='bulkGenerateAudit' && $_SERVER['REQUEST_METHOD']==='POST') {`n    requireAdmin(); verifyCsrf(); $d=input();`n    $total=(int)($d['total']??0);`n    $succeeded=(int)($d['succeeded']??0);`n    $failed=(int)($d['failed']??0);`n    $templateId=$d['template_id']??null;`n    auditLog('bulk_ids_generated','id_card',null,null,[`n      'total'=>$total,`n      'succeeded'=>$succeeded,`n      'failed'=>$failed,`n      'template_id'=>$templateId,`n      'generated_ids'=>$d['generated_ids']??[],`n    ]);`n    response(['success'=>true,'message'=>'Bulk generation recorded in audit log']);`n  }`n  response(['success'=>false,'message'=>'Unknown action'],404);`n} catch(Throwable $e){response(['success'=>false,'message'=>$e->getMessage()],500);}